window.KG_XC = [{"set": 1, "date": "2026-10-09", "session": "am", "title": "行测加练 · 科学推理 + 数量关系 + 判断推理（第 1 批）", "items": [{"type": "sci", "level": "中等", "stem": "用弹簧测力计水平拉木块，使木块在水平桌面上做匀速直线运动，此时弹簧测力计的示数为 2N。若保持接触面粗糙程度不变，把木块上的砝码取走，再次水平拉动木块使其做匀速直线运动，则弹簧测力计的示数将（　　）", "options": ["仍然为 2N", "大于 2N", "小于 2N 但大于 0", "无法判断"], "answer": ["C"], "explain": "木块做匀速直线运动时，水平方向受力平衡，拉力等于滑动摩擦力。取走砝码后，木块对桌面的压力减小；在接触面粗糙程度不变的情况下，滑动摩擦力随压力减小而减小，因此为维持匀速运动所需的拉力也变小，示数小于 2N 但仍大于 0。", "tip": "匀速直线运动 → 拉力 = 滑动摩擦力；滑动摩擦力大小只由「压力」和「接触面粗糙程度」决定。取走砝码改变了压力，摩擦力随之变小。", "method": "受力分析：先判断平衡（匀速 → 二力平衡），再判断摩擦力如何随压力变化。"}, {"type": "sci", "level": "容易", "stem": "把一根筷子斜插入水中，从水面上方看去，筷子好像在水面处「折断」了。对这一现象，正确的解释是（　　）", "options": ["光沿直线传播", "光发生了反射", "光发生了折射", "光发生了色散"], "answer": ["C"], "explain": "光从水中斜射入空气时，在水面处传播方向发生偏折，这就是光的折射。筷子反射的光经水面折射后进入人眼，人眼逆着折射光线看到的是筷子的虚像，位置比实际偏上，因此看起来像「折断」了。", "tip": "折射发生在「光斜射入另一种介质」时；反射是光在同一介质（表面）返回。关键是介质是否改变、是否斜射。", "method": "看到「水中的物体位置偏移/折断」→ 先想折射。"}, {"type": "sci", "level": "中等", "stem": "生活中，要降低水的硬度，下列做法有效的是（　　）", "options": ["静置沉淀", "过滤", "煮沸", "加入食盐"], "answer": ["C"], "explain": "水的硬度主要由水中可溶性的钙、镁化合物（如碳酸氢钙）引起。煮沸时，碳酸氢钙等受热分解生成难溶的碳酸钙沉淀，从而降低水中钙、镁离子的浓度，达到软化水的目的。静置沉淀和过滤只能除去不溶性杂质，不能除去可溶性钙镁化合物。", "tip": "区分「除不溶性杂质」（沉淀、过滤）和「降低硬度」（煮沸、蒸馏）。硬度是『可溶性』钙镁造成的。", "method": "硬水软化：生活中用煮沸，实验室用蒸馏。"}, {"type": "sci", "level": "容易", "stem": "把一粒种子萌发后长成的幼苗放在黑暗处培养一段时间，幼苗逐渐变黄。这一现象最能说明（　　）", "options": ["叶绿素的形成需要光", "种子的萌发需要光", "暗处植物不能进行呼吸作用", "幼苗体内的水分被不断消耗"], "answer": ["A"], "explain": "植物叶片呈绿色是因为含有叶绿素，而叶绿素只有在有光的条件下才能形成。幼苗在黑暗处不能合成叶绿素，叶片因此变黄。种子萌发本身不需要光，呼吸作用在暗处也照常进行。", "tip": "「光是叶绿素形成的条件」——缺光→叶黄，这是经典考点，别和「光合作用需要光」混淆。", "method": "看到「暗处变黄」→ 指向叶绿素合成需要光。"}, {"type": "math", "level": "容易", "stem": "一项工程，甲单独做需要 10 天完成，乙单独做需要 15 天完成。若两人合作，完成这项工程需要（　　）天。", "options": ["5", "6", "7", "8"], "answer": ["B"], "explain": "设工程总量为 10 与 15 的最小公倍数 30，则甲的效率为 30÷10＝3，乙的效率为 30÷15＝2，两人合作效率为 3＋2＝5。所需时间＝30÷5＝6（天）。", "method": "赋值法：工程问题把总量设为完工天数的公倍数，各人效率即为整数，运算最简。", "tip": "时间之比 10∶15＝2∶3，则效率之比为 3∶2（反比）；合作时间一定小于甲单干，别错选 5。"}, {"type": "logic", "level": "中等", "stem": "行政诉讼是指公民、法人或其他组织认为行政机关及其工作人员的具体行政行为侵犯其合法权益，依法向人民法院提起诉讼、由人民法院审理的活动。根据上述定义，下列属于行政诉讼的是（　　）", "options": ["李某因不服所在单位对其作出的降职处分，向法院起诉单位", "王某对交警大队对其作出的罚款处罚不服，向人民法院提起诉讼", "张某因邻居侵占其宅基地，向人民法院提起民事诉讼", "某公司因合同纠纷，向人民法院起诉另一家公司"], "answer": ["B"], "explain": "行政诉讼有三个要件：①被告须是行政机关；②针对的是具体行政行为；③向人民法院起诉。B 中被告是交警大队（行政机关），争议是罚款（具体行政行为），完全符合。A 的被告是单位（非行政机关），是内部人事争议；C、D 都是平等民事主体之间的纠纷。", "method": "定义判断：把定义的要素逐条列出（主体/对象/行为），拿选项逐一比对，缺一即排除。", "tip": "记住行政诉讼的内核是「民告官」——被告必须是行政机关，争的是具体行政行为；内部处分、平等主体纠纷都不算。"}]}, {"set": 2, "date": "2026-10-10", "session": "am", "title": "行测加练 · 科学推理 + 数量关系 + 判断推理（第 2 批）", "difficulty": "基础+中等", "items": [{"type": "sci", "level": "中等", "stem": "把一只鸡蛋放入盛水的烧杯中，鸡蛋沉底；向水中逐渐加盐并搅拌，鸡蛋恰好悬浮；继续加盐后鸡蛋最终漂浮在水面。下列说法正确的是（　）", "options": ["鸡蛋悬浮时所受的浮力小于沉底时所受的浮力", "鸡蛋漂浮时所受的浮力等于它所受的重力", "从沉底到漂浮的整个过程中，鸡蛋受到的浮力始终不变", "鸡蛋漂浮时排开盐水的体积比悬浮时排开盐水的体积大"], "answer": ["B"], "explain": "沉底时浮力小于重力；悬浮和漂浮时浮力都等于重力，故 B 正确。加盐后液体密度增大，同一只鸡蛋排开液体的体积不变（仍浸没）时浮力变大，所以悬浮浮力大于沉底浮力，A 错；整个过程浮力并不恒定，C 错；漂浮时浮力仍等于重力，而盐水密度更大，由 F浮＝ρ液gV排 可知排开体积反而变小，D 错。", "tip": "“悬浮”与“漂浮”都满足 F浮＝G物；区别在 V排：悬浮时 V排＝V物，漂浮时 V排＜V物。", "method": "先受力分析定浮力大小（沉底 F浮＜G，悬浮/漂浮 F浮＝G），再据 F浮＝ρ液gV排 判断排开体积。"}, {"type": "sci", "level": "容易", "stem": "下列关于金属与金属材料的说法，正确的是（　）", "options": ["钢和生铁都是铁碳合金，其中钢的含碳量比生铁高", "铁在潮湿的空气中容易生锈，表面镀锌可有效防锈", "铜的导电性比银强，因此常用铜制作电线", "铝合金的硬度比纯铝小"], "answer": ["B"], "explain": "铁在潮湿空气中与氧气、水共同作用容易生锈，镀锌能隔绝空气和水并起电化学保护作用，故 B 正确。生铁含碳量（2%～4.3%）高于钢（0.03%～2%），A 错；导电性银最强、铜次之，C 错；合金的硬度一般大于其成分纯金属，铝合金硬度比纯铝大，D 错。", "tip": "记三组对比：生铁含碳＞钢；合金硬度＞成分纯金属；导电性银＞铜＞铝。", "method": "逐项对照金属材料的基本性质与合金规律，排除法定位。"}, {"type": "sci", "level": "中等", "stem": "关于绿色植物的光合作用与呼吸作用，下列说法正确的是（　）", "options": ["光合作用只在白天进行，呼吸作用只在夜间进行", "光合作用在叶绿体中进行，呼吸作用在活细胞内进行", "光合作用消耗氧气、释放二氧化碳", "呼吸作用储存能量并释放氧气"], "answer": ["B"], "explain": "光合作用在叶绿体中进行，呼吸作用在活细胞（主要在细胞的线粒体）内昼夜不停地进行，故 B 正确。呼吸作用昼夜都有，A 错；光合作用吸收二氧化碳、释放氧气，C 说反了；呼吸作用分解有机物、释放能量并放出二氧化碳，D 错。", "tip": "一句话记：光合“吸碳放氧、储能量”，呼吸“吸氧放碳、释能量”；呼吸昼夜不停，光合需要光照。", "method": "先分清两个过程的场所、原料产物与能量变化，再逐项对照。"}, {"type": "sci", "level": "容易", "stem": "关于声现象，下列说法正确的是（　）", "options": ["声音在真空中传播得最快", "“闻其声知其人”主要依据的是音调", "高速公路旁的隔音墙是在传播过程中减弱噪声", "超声波不能在水中传播"], "answer": ["C"], "explain": "声音的传播需要介质，真空不能传声，A 错；“闻其声知其人”主要依据音色而非音调，B 错；隔音墙是在声音的传播过程中减弱噪声，C 对；超声波可以在水、固体等介质中传播，声呐就是利用超声波在水中定位，D 错。", "tip": "记三句：真空不传声；辨人靠音色；隔音墙属“传播过程中”减弱噪声。", "method": "对照声音的产生、传播条件与三特性逐项判断。"}, {"type": "math", "level": "容易", "stem": "将质量分数 20% 的盐水 200 克与质量分数 5% 的盐水 300 克混合，混合后盐水的质量分数为（　）", "options": ["10%", "11%", "12.5%", "15%"], "answer": ["B"], "explain": "盐的总量＝200×20%＋300×5%＝40＋15＝55（克），溶液总质量＝200＋300＝500（克），质量分数＝55÷500＝11%，故选 B。", "tip": "浓度混合题算“溶质之和÷溶液之和”，切忌把两个百分数直接平均（直接平均会得到 12.5%）。", "method": "先分别求溶质，相加后再除以溶液总质量。"}, {"type": "math", "level": "中等", "stem": "甲、乙两人分别从相距 36 千米的两地同时出发相向而行，甲每小时走 5 千米，乙每小时走 4 千米。甲带的一条狗以每小时 8 千米的速度在两人之间往返奔跑，直到两人相遇时狗才停下。狗一共跑了多少千米？（　）", "options": ["24 千米", "28 千米", "32 千米", "36 千米"], "answer": ["C"], "explain": "狗奔跑的总时间＝两人从出发到相遇的时间。相遇时间＝36÷(5＋4)＝4（小时），故狗跑的路程＝8×4＝32（千米），选 C。", "tip": "“往返跑”类题不用逐段累加，抓“时间相同”即可：狗跑的时间＝两人相遇所需时间。", "method": "先求相遇时间（路程÷速度和），再乘狗的速度。"}, {"type": "math", "level": "中等", "stem": "某商品按获利 20% 定价，后来按定价打八折出售，结果亏了 40 元。该商品的进价是多少元？（　）", "options": ["800 元", "1000 元", "1200 元", "1500 元"], "answer": ["B"], "explain": "设进价为 x 元。定价＝1.2x，打八折后售价＝1.2x×0.8＝0.96x。由“亏 40 元”得 x－0.96x＝0.04x＝40，解得 x＝1000（元），选 B。", "tip": "利润率的单位“1”是进价；先算出实际售价比进价少百分之几（本题少 4%），再对应亏损额。", "method": "设进价为 x，写出定价→折后售价，用亏损额列一元一次方程。"}, {"type": "logic", "level": "中等", "stem": "沉没成本是指由于过去的决策已经发生、而不能由现在或将来的任何决策改变的成本。根据上述定义，下列属于沉没成本的是（　）", "options": ["小王为看一场电影已购买的、不可退换的电影票", "某公司为新增生产线向银行申请的贷款利息", "小李为了将来出国留学而报名的英语培训班费用", "企业为扩大生产而计划投入的设备购置预算"], "answer": ["A"], "explain": "沉没成本有两个要件：过去已发生、且不可改变。A 中电影票已购买且不可退换，符合定义。B 贷款利息是针对未来的支出；C 培训费用指向将来收益；D 设备购置属尚未发生的计划投入，均可改变，故排除。", "tip": "定义判断抓“关键要件”：本题要件是“已发生＋不可改变”，逐项比对即可。", "method": "提取定义的两个要件，逐项检验选项是否同时满足。"}, {"type": "logic", "level": "容易", "stem": "医生∶手术刀，与下列哪组词的逻辑关系最为相似？（　）", "options": ["画家∶画笔", "农民∶土地", "学生∶课本", "工人∶工资"], "answer": ["A"], "explain": "题干是“职业与其所使用的工具”的对应关系：医生使用手术刀。A 中画家使用画笔，关系一致。B 土地是农民的劳动对象（场所）而非工具；C 课本是学生使用的学习材料，但学生不是职业、且重点在“学习用品”而非“操作工具”；D 工资是工人的报酬，与题干关系不符。", "tip": "类比先定关系大类（工具/对象/原料/产物…），再比“是否同为职业与操作工具”。", "method": "先判题干关系类型，再逐项验证是否为同一种关系。"}, {"type": "logic", "level": "中等", "stem": "某单位要选派人员参加比赛。已知条件：（1）如果派甲去，则必须派乙去；（2）只有派丙去，才派丁去；（3）甲和丙两人中至少派一人；（4）不派乙去。据此可以推出（　）", "options": ["一定派甲去", "一定派丙去", "一定派丁去", "甲和丁都被派去"], "answer": ["B"], "explain": "（4）不派乙。（1）甲→乙，结合“不派乙”逆否可得不派甲。（3）甲和丙至少一人，既然不派甲，则必派丙。（2）丁→丙，丙被派并不能反推丁，故丁是否派去无法确定。唯一能确定的是“一定派丙去”，选 B。", "tip": "“只有…才…”表示后者是前者的必要条件（前→后）；“如果…则…”表示前者是充分条件（前→后）。善用逆否命题。", "method": "把条件符号化（甲→乙、丁→丙、甲∨丙、¬乙），从头逆推链条。"}, {"type": "fig", "imgs": ["data/figs/figq_001_1.png", "data/figs/figq_001_2.png"], "src": "", "cat": "", "fmt": "", "stem": "选择最合适的完成图形推理：", "options": ["", "", "", "", ""], "answer": ["C"], "explain": "前三个图形，图一图二都有圆，图三是圆。图一图二是两个图形，图三是一个图形。后三个图形应该也是一样的道理，图一图二都有三角形，所以图三是三角形，图一图二是两个图形，图三是一个图形。只有选项C符合，所以选C。", "trap": ""}, {"type": "fig", "imgs": ["data/figs/figq_002_1.png"], "src": "", "cat": "", "fmt": "", "stem": "根据以上图形的规律，下一个图形应该是：", "options": ["", "", "", ""], "answer": ["B"], "explain": "看小黑点和竖线，第二列，小黑点在竖线的左侧，竖线每次旋转45°；第三列竖线每次旋转45°，每转一次小黑点位置就变一次，右，左，右，左。", "trap": ""}]}, {"set": 3, "date": "2026-10-10", "session": "pm", "title": "行测加练 · 科学推理 + 数量关系 + 判断推理（第 3 批）", "items": [{"type": "sci", "level": "容易", "stem": "把一根筷子斜插入盛水的玻璃杯中，从侧面看，筷子好像在水面处“折断”了。这一现象说明：", "options": ["光在水中不沿直线传播", "光从水斜射入空气时发生了折射", "光总是沿曲线传播", "水面把筷子切断了"], "answer": ["B"], "explain": "光从水斜射入空气时，传播方向在两介质交界处发生偏折，这就是光的折射；人眼仍沿折射光线的反向看去，便产生了“折断”的错觉。光在同种均匀介质中沿直线传播，A、C 错；D 显然错误。故选 B。", "method": "判断光学现象先分类：同种均匀介质→沿直线传播（影子、小孔成像）；斜射到界面、进入另一介质→折射（筷子折断、水变浅）；遇到反射面→反射（倒影、平面镜）。", "tip": "别把“折射”当成“反射”——看有没有“界面”并“进入另一种介质”。", "hard": "“光的反射”与“光的折射”最易混。"}, {"type": "sci", "level": "容易", "stem": "一个物体在水平面上做匀速直线运动，则它受到的力：", "options": ["一定不受任何力的作用", "一定是平衡力", "一定是非平衡力", "以上都不对"], "answer": ["B"], "explain": "物体做匀速直线运动，速度的大小和方向都不变，处于平衡状态，所受的力一定是平衡力（合力为零）。物体受重力、支持力等，并非不受力，A 错；既然匀速，就不是非平衡力，C 错。故选 B。", "method": "记“平衡状态”：静止或做匀速直线运动⇒受力平衡，合力为零。", "tip": "“匀速”不等于“不受力”，而是“受平衡力”。", "hard": ""}, {"type": "sci", "level": "容易", "stem": "一个木块漂浮在水面上，则它受到的浮力与物体重力的大小关系是：", "options": ["浮力大于重力", "浮力小于重力", "浮力等于重力", "无法比较"], "answer": ["C"], "explain": "木块漂浮时处于静止（平衡）状态，竖直方向只受浮力和重力两个力，二力平衡，故浮力等于重力。故选 C。", "method": "漂浮、悬浮均为平衡状态，F浮＝G；下沉时 F浮＜G；从水底上浮过程中 F浮＞G。", "tip": "漂浮和悬浮都是平衡状态、浮力都等于重力，区别在于物体密度与液体密度的大小关系。", "hard": ""}, {"type": "sci", "level": "中等", "stem": "把一盆绿色植物放到黑暗处一昼夜后，用黑纸片把一片叶的一部分遮住，再光照几小时，摘下后经酒精脱色、滴加碘液处理。观察到的现象是：", "options": ["遮光部分变蓝，见光部分不变蓝", "见光部分变蓝，遮光部分不变蓝", "整片叶都变蓝", "整片叶都不变蓝"], "answer": ["B"], "explain": "见光部分进行了光合作用，产生了淀粉，遇碘变蓝；遮光部分见不到光，不能进行光合作用、没有淀粉，故不变蓝。故选 B。", "method": "验证“光合作用需要光”：黑暗处理→部分遮光→光照→酒精脱色→滴碘。见光部分变蓝，说明有淀粉生成。", "tip": "“黑暗处一昼夜”是为了耗尽叶片中原有的淀粉，否则结果不可靠，别漏这一步。", "hard": "容易忽略“先暗处理”的作用。"}, {"type": "math", "level": "容易", "stem": "一项工程，甲单独做需要 10 天完成，乙单独做需要 15 天完成。两人合作，需要多少天完成？", "options": ["5 天", "6 天", "8 天", "12 天"], "answer": ["B"], "explain": "把工程总量设为 1，甲每天做 1/10，乙每天做 1/15，合作每天做 1/10＋1/15＝3/30＋2/30＝5/30＝1/6，故需要 6 天。故选 B。", "method": "赋值法：取工作时间的最小公倍数作总量。10、15 的最小公倍数是 30，甲 3、乙 2，合计 5，则 30÷5＝6 天。", "tip": "别把天数直接相加（10＋15＝25 是常见错解）；效率才能相加，时间不能。", "hard": ""}, {"type": "math", "level": "中等", "stem": "浓度为 20% 的盐水 200 克，要使其浓度变为 25%，需要蒸发掉多少克水？", "options": ["30 克", "40 克", "50 克", "60 克"], "answer": ["B"], "explain": "盐的质量＝200×20%＝40 克，蒸发水时盐的质量不变。设蒸发 x 克水，则 40/(200−x)＝25%，解得 200−x＝160，x＝40 克。故选 B。", "method": "浓度问题抓“不变量”：加水时盐不变，蒸发水时盐也不变，用溶质质量列方程。", "tip": "先算溶质（盐）质量，再按新浓度反推溶液总量，别拿 200 直接乘 5%。", "hard": ""}, {"type": "math", "level": "中等", "stem": "甲、乙两人从相距 36 千米的两地同时出发，相向而行，甲每小时走 5 千米，乙每小时走 4 千米。经过几小时两人相遇？", "options": ["3 小时", "4 小时", "4.5 小时", "5 小时"], "answer": ["B"], "explain": "相向而行时，两人的速度和＝5＋4＝9（千米/时），相遇时间＝总路程÷速度和＝36÷9＝4 小时。故选 B。", "method": "相遇问题：时间＝总路程÷速度和；追及问题：时间＝路程差÷速度差。", "tip": "先分清“相向（求和）”还是“同向（求差）”，别把速度和、速度差用反。", "hard": ""}, {"type": "logic", "level": "中等", "stem": "光环效应，是指人们对他人的认知判断首先根据个人的好恶得出，然后再从这个判断推论出认知对象的其他品质的现象。根据上述定义，下列属于光环效应的是：", "options": ["因为小李待人热情，大家便认为他工作也一定认真负责", "小李工作认真，同事们都愿意与他合作", "小李因为个子高，被选进了学校篮球队", "小李因为成绩优异，获得了奖学金"], "answer": ["A"], "explain": "光环效应的关键要件是“由对某一特点的好印象，推及其他并不相关的品质”。A 由“待人热情”推出“工作认真负责”，正是以点带面的推论，符合定义。B 是正常因果；C、D 都是某一条件导致的相关结果，不存在“推及其他品质”。故选 A。", "method": "定义判断：先圈出定义的关键要件（主体、方式、结果），再逐项比对，缺件即排除。", "tip": "抓住“由已知的某一特征推及其他无关品质”这一核心要件。", "hard": ""}, {"type": "logic", "level": "容易", "stem": "医生∶手术刀（　）", "options": ["画家∶画笔", "病人∶医院", "老师∶学生", "农民∶土地"], "answer": ["A"], "explain": "医生使用手术刀作为职业工具，二者是“职业—工具”关系。A 画家使用画笔，同样是职业—工具关系；B 是“人—场所”，C 是“人—对象”，D 是“人—劳动对象（场所）”。故选 A。", "method": "类比推理先定题干关系（工具/场所/对象/因果/并列……），再到选项里找同一种关系的。", "tip": "分清“工具”与“对象”：手术刀是工具，土地是被作用的对象。", "hard": ""}, {"type": "logic", "level": "中等", "stem": "只有努力学习，才能考上理想的大学。小李没有考上理想的大学。由此可以推出：", "options": ["小李一定没有努力学习", "小李一定努力学习了", "小李可能没有努力学习", "小李学习很努力，只是发挥失常"], "answer": ["C"], "explain": "“只有努力，才能考上”表示“考上→努力”（努力是考上的必要条件）。小李没考上，是否定了后件，不能必然推出他是否努力，只能说“可能没有努力”。A 把“可能”误当成“必然”；B、D 更无从推出。故选 C。", "method": "必要条件命题“只有 A 才 B”可写成“B→A”：肯定后件必肯定前件；否定后件推不出确定结论，只能得到“可能”。", "tip": "“只有……才……”是必要条件，切忌由“没考上”直接推成“没努力”。", "hard": "充分条件与必要条件容易记反。"}, {"type": "fig", "imgs": ["data/figs/figq_003_1.png", "data/figs/figq_003_2.png"], "src": "", "cat": "", "fmt": "", "stem": "空缺处的图形应当是：", "options": ["", "", "", ""], "answer": ["A"], "explain": "一行看过去，前两个合并叠加，等于第三个。", "trap": ""}, {"type": "fig", "imgs": ["data/figs/figq_004_1.png"], "src": "", "cat": "", "fmt": "", "stem": "根据以上图形规律，下一个图形应该是：", "options": ["", "", "", ""], "answer": ["C"], "explain": "把线条分为上下方向移动和左右方向移动，横线从下往上移动一个单位（移到最顶部再移动就回到最底部），竖线从左往右移动一个单位（移到最右边再移动就回到最左边）。", "trap": ""}]}, {"set": 4, "date": "2026-10-11", "session": "am", "title": "行测加练 · 科学推理 + 数量关系 + 判断推理（第 4 批）", "items": [{"type": "sci", "level": "容易", "stem": "在水平地面上，用水平推力推一个静止的木箱，木箱未被推动。下列说法正确的是：", "options": ["木箱受到的推力小于摩擦力", "木箱受到的静摩擦力与推力大小相等、方向相反", "木箱受到的静摩擦力大于推力", "木箱不受摩擦力"], "answer": ["B"], "explain": "木箱保持静止，处于平衡状态，水平方向上推力与静摩擦力是一对平衡力，二者大小相等、方向相反，故选 B。A、C 把大小关系说反了，只要木箱没被推动，静摩擦力就始终等于推力；D 错误，木箱虽静止但有相对地面滑动的趋势，必然受到静摩擦力。", "method": "受力平衡法：先判断物体处于什么运动状态，再对水平方向作二力平衡分析。", "tip": "静摩擦力的大小随外力变化而变化，不能直接套用滑动摩擦力的公式 f＝μN。", "hard": "把“静摩擦力”当成“滑动摩擦力”去套公式。"}, {"type": "sci", "level": "中等", "stem": "下列关于生活中常见现象的解释，错误的是：", "options": ["铁在潮湿的空气中容易生锈，是因为铁与氧气和水共同作用", "用食醋可以除去水壶中的水垢，是因为醋酸能与水垢中的碳酸钙反应", "新装修的房间有刺鼻气味，主要是甲醛等物质挥发造成的", "冬天用煤炉取暖要开窗通风，是因为煤不完全燃烧会产生二氧化碳"], "answer": ["D"], "explain": "D 的解释错误：煤在氧气不足时不充分燃烧，产生的有毒气体主要是一氧化碳（CO），而不是二氧化碳，所以必须开窗通风以防中毒，故选 D。A、B、C 的解释均符合化学原理：铁生锈需氧气和水，醋酸可与碳酸钙反应，新装修的刺激性气味多由甲醛等挥发造成。", "method": "逐一判断法：把每个选项当作一个独立的化学小结论去核对，选出明显违背生活化学常识的一项。", "tip": "一定要区分一氧化碳和二氧化碳：前者有毒、可致人中毒，后者本身无毒，这是常见误区。", "hard": "“一氧化碳”与“二氧化碳”混淆。"}, {"type": "sci", "level": "中等", "stem": "关于人体消化系统，下列说法正确的是：", "options": ["胃是消化和吸收营养物质的主要器官", "小肠内表面有许多皱襞和小肠绒毛，有利于营养物质的吸收", "胆汁中含有消化脂肪的酶", "食物中的淀粉在口腔中开始被消化为葡萄糖"], "answer": ["B"], "explain": "小肠内壁有大量皱襞和小肠绒毛，极大增加了消化和吸收的面积，使小肠成为消化吸收的主要器官，故选 B。A 错在把主要器官说成了胃；C 错在胆汁并不含消化酶，它只是把脂肪乳化成小颗粒；D 错在口腔中淀粉被分解为麦芽糖，而不是葡萄糖。", "method": "抓结构与功能相适应：看哪个选项把器官的结构与它的生理功能对应得最合理。", "tip": "牢记两点：胆汁不含消化酶；淀粉在口腔只被消化成麦芽糖，最终在小肠才变成葡萄糖。", "hard": "误以为胆汁中含有消化脂肪的酶。"}, {"type": "sci", "level": "容易", "stem": "夏天从冰箱中取出一瓶冰镇饮料，放置一会儿后，瓶外壁出现许多小水珠。对该现象的分析，正确的是：", "options": ["是瓶内的饮料渗漏到瓶外形成的", "是瓶外空气遇冷凝固形成的", "是空气中的水蒸气遇冷液化形成的", "小水珠形成的过程中要吸收热量"], "answer": ["C"], "explain": "瓶壁温度很低，空气中的水蒸气接触到冷瓶壁后放热液化成小水珠附着在瓶外，故选 C。A 属无中生有，瓶内液体并未渗漏；B 错在把液化说成凝固，凝固是液态变固态；D 错在液化过程要放热，而不是吸热。", "method": "物态变化判断题：先判断物质变化前后各是什么状态，再对应相应物态变化的名称与吸放热情况。", "tip": "液化的关键是“气态→液态”，且液化放热，别与凝固、汽化混淆。", "hard": "把“液化”与“凝固”弄混，或记错吸放热。"}, {"type": "math", "level": "中等", "stem": "一项工程，甲单独做需要 10 天完成，乙单独做需要 15 天完成。若甲先单独做 2 天后，再由甲、乙两人合作完成剩余工程，则完成这项工程共需要多少天？", "options": ["6 天", "6.5 天", "6.8 天", "7 天"], "answer": ["C"], "explain": "设工作总量为 30（10 和 15 的最小公倍数），则甲效率为 3、乙效率为 2。甲先做 2 天完成 3×2＝6，剩余 30－6＝24；两人合作效率为 3＋2＝5，需 24÷5＝4.8 天。总时间为 2＋4.8＝6.8 天，故选 C。A、B、D 多为只算合作时间或取整出错。", "method": "赋值法：把工作总量赋为两人单独完成天数的公倍数，便于快速算出各自效率。", "tip": "题目问的是“完成这项工程总共需要多少天”，要把甲先单独做的 2 天加上，别只算合作天数。", "hard": "漏掉甲先单独做的 2 天，只算合作时间。"}, {"type": "math", "level": "容易", "stem": "甲、乙两数之和为 60，甲数比乙数的 2 倍少 6，则甲、乙两数分别是：", "options": ["36 和 24", "38 和 22", "40 和 20", "34 和 26"], "answer": ["B"], "explain": "设乙数为 x，则甲数为 2x－6，由题意得 (2x－6)＋x＝60，即 3x－6＝60，解得 x＝22，甲数为 2×22－6＝38，故选 B。其余选项代入都不能同时满足“和为 60”且“甲比乙的 2 倍少 6”两个条件。", "method": "方程法：设较小的数为未知数，把另一个数用含未知数的式子表示，再根据数量关系列方程求解。", "tip": "“比乙数的 2 倍少 6”是 2x－6，不要写成 2(x－6)，少 6 是在整体 2x 上减去 6。", "hard": "把“2x－6”错写成“2(x－6)”。"}, {"type": "math", "level": "中等", "stem": "某商品按成本加价 50% 标价，后因促销按标价打八折出售，则每件商品的利润率是多少？", "options": ["15%", "25%", "30%", "20%"], "answer": ["D"], "explain": "设成本为 100，则标价为 100×(1＋50%)＝150，八折售价为 150×0.8＝120，利润为 120－100＝20，利润率＝20÷100×100%＝20%，故选 D。A、B、C 多因把折扣或加价率算错，或把利润除以售价而得到。", "method": "赋值法：直接设成本为 100，按顺序算出标价、售价、利润，最后套利润率公式。", "tip": "利润率＝利润÷成本×100%，分母是“成本”而不是“售价”，两者相差较大，是最常见的失分点。", "hard": "把利润率的分母错用成“售价”。"}, {"type": "logic", "level": "中等", "stem": "破窗效应是指：环境中的不良现象如果被放任存在，会诱使人们仿效，甚至变本加厉。根据上述定义，下列不属于破窗效应的是：", "options": ["一面墙上出现一些涂鸦没有被及时清洗掉，很快墙上就布满了乱七八糟的东西", "某广场干净整洁时没人乱扔垃圾，一旦有人扔了垃圾而无人制止，不久地上就到处是垃圾", "一栋房子的窗户破了没人修补，过不了多久，其他窗户也会被人打破", "小明坚持每天早起晨跑，受他影响，同学们也纷纷开始早起晨跑"], "answer": ["D"], "explain": "题干定义强调“不良现象被放任→诱使他人仿效并变本加厉”，而 D 中“早起晨跑”是良好的行为习惯，同学们仿效的是正面行为，与定义中“不良现象”这一要件不符，故选 D。A、B、C 都符合“不良现象被放任后被纷纷效仿”的特征。", "method": "定义判断抓要件：把定义拆成“不良现象＋被放任＋被仿效并加重”几个关键要件，逐一对照选项。", "tip": "务必抓住“不良现象”这个核心前提，正面行为的带动再像也不属于破窗效应。", "hard": "只看“被仿效”就选，忽略“不良现象”这一前提。"}, {"type": "logic", "level": "容易", "stem": "医生∶手术刀 相当于：", "options": ["画家∶画笔", "农民∶土地", "学生∶书本", "司机∶乘客"], "answer": ["A"], "explain": "医生工作时要使用手术刀，二者是“职业与其使用的工具”的对应关系，画家工作时使用画笔，同样是职业与工具的对应，故选 A。B 中土地是农民劳作的场所；C 中书本是学生学习的对象或资料，工具色彩不如 A 直接；D 中乘客是司机的服务对象。", "method": "类比推理先定关系：准确概括出题干两词的关系类型，再找与之关系最贴近、最一致的一项。", "tip": "要比较关系的“同一性”，不能只看是否相关；场所、对象、工具三种关系要分辨清楚。", "hard": "把“场所关系”“对象关系”误当成“工具关系”。"}, {"type": "logic", "level": "较难", "stem": "某研究表明，经常喝咖啡的人患某种疾病的概率明显低于不喝咖啡的人。因此，研究人员认为喝咖啡能降低患该疾病的风险。以下哪项如果为真，最能削弱上述结论？", "options": ["这项研究的样本量相对较小，结论的可靠性有待进一步验证", "经常喝咖啡的人往往也更注重锻炼身体和饮食健康，而这些习惯本身就能降低患病风险", "咖啡中含有一些对人体有益的抗氧化物质", "不喝咖啡的人群中，也有很多人身体十分健康"], "answer": ["B"], "explain": "题干由“喝咖啡者患病少”直接推出“喝咖啡能降低患病风险”。若 B 成立，说明患病少可能是锻炼和饮食健康等“其他因素”造成的，而非咖啡本身，属于典型的“另有他因”削弱，削弱力度最强，故选 B。A 只是说样本量小，削弱力度较弱；C 反而支持结论；D 与结论无直接关系。", "method": "削弱题抓“因果链”：题干由相关关系推因果关系，削弱应优先找“另有他因”或“因果倒置”。", "tip": "削弱力度要比较：直接斩断因果（另有他因）强于笼统质疑研究的可靠性，别被“样本小”这类弱选项带走。", "hard": "被“样本量小”这类弱削弱项迷惑，忽略“另有他因”的强削弱。"}, {"type": "fig", "imgs": ["data/figs/figq_005_1.png", "data/figs/figq_005_2.png"], "src": "", "cat": "", "fmt": "", "stem": "问号处的图形应该是：", "options": ["", "", "", ""], "answer": ["A"], "explain": "每一行都是两个黑球两个白球。", "trap": ""}, {"type": "fig", "imgs": ["data/figs/figq_006_1.png", "data/figs/figq_006_2.png"], "src": "", "cat": "", "fmt": "", "stem": "问号处的图形应该是：", "options": ["", "", "", ""], "answer": ["A"], "explain": "第一个图中，左边到中间规律是：第一个移到最后，全体箭头换方向中间到后边同理。", "trap": ""}]}, {"set": 5, "date": "2026-10-11", "session": "pm", "title": "行测加练 · 科学推理 + 数量关系 + 判断推理（第 5 批）", "items": [{"type": "sci", "level": "容易", "stem": "把一根筷子斜插入水中，从水面上方看，筷子在水中的部分好像“折断”了。这是因为（　）", "options": ["光从水中斜射入空气时发生了折射", "光在水中发生了反射", "光沿直线传播被水挡住了", "水面发生了漫反射"], "answer": ["A"], "explain": "筷子反射的光从水中斜射入空气时，在水面处改变传播方向，人眼逆着光线看去，就觉得筷子在水中“变折”了，这是光的折射，选 A。B、D 是反射现象，C 与现象不符。", "method": "看到水中的物体“位置变了/折断/变浅”，都是折射（光从一种介质斜射入另一种介质）；看到水中倒影才是反射。", "tip": "折射的关键词是“斜射入另一种介质”，垂直入射时不偏折。", "hard": "注意区分：看水中的鱼“变浅”、筷子“折断”是折射；看水面的倒影是反射。"}, {"type": "sci", "level": "容易", "stem": "关于惯性，下列说法正确的是（　）", "options": ["物体只有在静止时才有惯性", "惯性的大小只与物体的质量有关，与速度无关", "运动越快的物体惯性越大", "物体受到的力越大，惯性越大"], "answer": ["B"], "explain": "惯性是物体保持原有运动状态的性质，是一切物体固有的属性，大小只由质量决定，与速度、受力都无关，B 正确。A、C、D 都把惯性与状态、速度或力混为一谈。", "method": "判惯性题只认“质量”一个量：质量越大惯性越大，其余条件一律不影响。", "tip": "“惯性”与“惯性定律（牛顿第一定律）”不是一回事，惯性是属性，不能被“产生”。", "hard": "常见陷阱：说“速度大惯性大”“受力大惯性大”——都是把惯性和运动状态、力混了。"}, {"type": "sci", "level": "中等", "stem": "某溶液的 pH＝3，向其中滴入紫色石蕊试液，溶液呈现的颜色是（　）", "options": ["红色", "蓝色", "紫色", "无色"], "answer": ["A"], "explain": "pH＝3＜7，溶液显酸性，紫色石蕊试液遇酸变红，故选 A。B 是石蕊遇碱的颜色，C 是中性时不变色，D 不符合石蕊变色的规律。", "method": "记石蕊口诀：遇酸变红、遇碱变蓝，中性紫色不变。先由 pH 判酸碱性，再看颜色。", "tip": "酚酞遇酸不变色（仍无色），石蕊遇酸变红——两种指示剂别记混。", "hard": "pH 越小酸性越强，但要看清题问的是“石蕊”还是“酚酞”。"}, {"type": "sci", "level": "中等", "stem": "一对夫妇均为 AB 型血，他们的子女可能的血型是（　）", "options": ["只能是 AB 型", "A 型或 B 型", "A 型、B 型或 AB 型", "A 型、B 型、AB 型或 O 型"], "answer": ["C"], "explain": "AB 型血的基因型为 I^A I^B，双亲各提供一个基因：可组合成 I^A I^A（A 型）、I^A I^B（AB 型）、I^B I^B（B 型），因此子女可能是 A、B、AB 型，选 C。O 型（ii）需要两个 i 基因，双亲均无 i，故不可能，排除 D。", "method": "血型遗传用“各取一个基因再两两组合”，列组合表即可；注意 O 型必须同时拿到两个 i。", "tip": "AB 型父母不可能生出 O 型孩子，这是最常见的干扰项。", "hard": "别忘了 A 型可能来自 I^A I^A 也可能 I^A i，但本题父母无 i，所以只出现 A、B、AB 三种。"}, {"type": "math", "level": "容易", "stem": "一项工程，甲单独做 10 天完成，乙单独做 15 天完成。两人合作，需要多少天完成？", "options": ["5 天", "6 天", "7 天", "8 天"], "answer": ["B"], "explain": "把工程总量设为“1”。甲每天做 1/10，乙每天做 1/15，合作每天做 1/10＋1/15＝3/30＋2/30＝5/30＝1/6，所以需要 6 天，选 B。", "method": "工程问题赋值法：总量设为 1（或设为两人效率的最小公倍数），合作时间＝1÷效率和。", "tip": "总量设 1 后，效率就是“每天完成几分之几”，别把 10 和 15 直接相加。", "hard": "若设总量为 30，则甲效率 3、乙效率 2，合作 30÷5＝6 天，结果一致，赋值更省事。"}, {"type": "math", "level": "中等", "stem": "某商品进价 80 元，标价 120 元。若按标价打八折出售，则利润率是（　）", "options": ["20%", "25%", "30%", "40%"], "answer": ["A"], "explain": "售价＝120×0.8＝96 元，利润＝96－80＝16 元，利润率＝利润÷进价＝16÷80＝20%，选 A。", "method": "利润率的分母永远是“进价（成本）”，不是标价、也不是售价。先算实际售价，再套公式。", "tip": "16÷120≈13.3% 是把分母用错（用了标价）的典型错法，正好对应干扰项附近。", "hard": "“打八折”是乘以 0.8；利润率＝(售价－进价)÷进价，两个易错点叠在一起。"}, {"type": "math", "level": "中等", "stem": "从 1、2、3、4、5 中任取两个不同的数字，组成一个两位数，一共能得到多少个不同的两位数？", "options": ["10 个", "15 个", "20 个", "25 个"], "answer": ["C"], "explain": "两位数有十位和个位，顺序不同算不同的数。十位有 5 种选法，个位在剩下的 4 个数字中选，共 5×4＝20 个，选 C。", "method": "“取两个不同数字组两位数”是有序排列：先定十位（5 种），再定个位（4 种），相乘。", "tip": "若问“任取两个数字组成一个集合/组合”才是 5×4÷2＝10 种，注意“两位数”隐含有序。", "hard": "选项里的 10 就是漏掉顺序（当成组合）的结果，要看清“组两位数”是否讲究顺序。"}, {"type": "logic", "level": "容易", "stem": "搭便车效应：指在集体行动中，个别人不付出成本却坐享集体收益的现象。根据上述定义，下列属于搭便车效应的是（　）", "options": ["小区业主共同出资修路，其中某户未出钱却照常通行", "顾客趁商场打折时低价购入心仪商品", "员工加班完成项目后获得了公司奖金", "农民在自家承包地里辛勤耕种，获得丰收"], "answer": ["A"], "explain": "A 中该户未出资（不付成本）却照常享用大家修的路（坐享集体收益），符合定义。B 是正常消费；C 付出了加班劳动并得到对等奖励；D 自己劳动自己收获，均不符合“不付成本却享集体收益”。", "method": "定义判断抓“要件”：①集体行动 ②不付成本 ③享受集体收益，三者同时满足才可入选，缺一个就排除。", "tip": "“搭便车”的关键是“不付出却受益”，不要被“打折”“奖励”这类无关词带偏。", "hard": "易错项是那些“看似占了便宜”的日常行为（如打折购物），其实并不涉及“集体行动”。"}, {"type": "logic", "level": "容易", "stem": "医生∶手术刀。下列选项中，与这一组关系最为相似的是（　）", "options": ["厨师∶菜刀", "教师∶钢笔", "农民∶土地", "作家∶小说"], "answer": ["A"], "explain": "“医生”是职业，“手术刀”是该职业工作时使用的专门工具，二者是“职业—工具”关系。A“厨师∶菜刀”同样是职业与其专用工具，故选 A。B 钢笔只是书写工具、并非教师专有；C 土地是劳动对象（场所），不是工具；D 小说是作家创作的产品。", "method": "类比题先给题干关系“定性”（职业与工具/对象/产品），再逐项对照，找关系最贴合的。", "tip": "区分“工具”与“对象”“产品”：手术刀是工具，土地是对象，小说是产品。", "hard": "B 迷惑性在于“教师也用笔”，但钢笔不是教师职业的专属工具（医生与手术刀则有强对应）。"}, {"type": "logic", "level": "较难", "stem": "甲、乙、丙三人中只有一人说真话。甲说：“乙在说谎。”乙说：“丙在说谎。”丙说：“甲和乙都在说谎。”由此可以推出（　）", "options": ["甲说真话", "乙说真话", "丙说真话", "三人都说真话"], "answer": ["B"], "explain": "设甲、乙、丙的话分别为 A、B、C。A＝“乙在说谎”＝非 B；B＝“丙在说谎”＝非 C；C＝“甲和乙都在说谎”＝非 A 且非 B。若 C 真，则 A、B 都假，但 A＝非 B 就为真，矛盾，故 C 假。C 假说明“A 假且 B 假”不成立，即 A、B 至少一真；又 A＝非 B，故 A、B 恰一真一假。若 A 真则 B 假，而 B＝非 C，由 C 假得 B 真，矛盾；故只能是 A 假、B 真。此时 C 假也成立。所以只有乙说真话，选 B。", "method": "真假话题用“假设法＋矛盾排除”：先假设某句为真，推出矛盾就否定它，剩下的唯一自洽情形即答案。", "tip": "把每句话写成“非某某”的等价式再推理，比空想更不容易乱。", "hard": "“只有一人说真话”是硬约束，推出的情形必须与之一致；本题“乙真、甲丙假”正好满足。"}, {"type": "fig", "imgs": ["data/figs/figq_007_1.png", "data/figs/figq_007_2.png"], "src": "", "cat": "", "fmt": "", "stem": "问号处的图形应该是：", "options": ["", "", "", "", ""], "answer": ["E"], "explain": "最底层相邻两个两两相加，得到上一层，相同消去，相异叠加。", "trap": ""}, {"type": "fig", "imgs": ["data/figs/figq_008_1.png"], "src": "", "cat": "", "fmt": "", "stem": "下列图形中不同于其他图形的一项是：", "options": ["", "", "", ""], "answer": ["A"], "explain": "其他图形都是两个元素组成，只有A是三个图形元素。", "trap": ""}]}, {"set": 6, "date": "2026-10-12", "session": "am", "title": "行测加练 · 科学推理 + 数量关系 + 判断推理（第 6 批）", "items": [{"type": "sci", "level": "容易", "stem": "小明用弹簧测力计沿水平方向拉一个放在水平桌面上的木块，木块保持静止。此时弹簧测力计的示数为 3N。下列说法正确的是：", "options": ["木块不受摩擦力", "木块受到的合力为 3N", "木块受到的摩擦力大于 3N", "木块受到的摩擦力大小为 3N，方向与拉力相反"], "answer": ["D"], "explain": "木块静止，水平方向受拉力和摩擦力，二力平衡，故摩擦力与拉力大小相等、方向相反，为 3N，合力为 0，D 对。A 忽略了摩擦力的存在；B、C 都违背了二力平衡条件。", "method": "先判断运动状态（静止/匀速 → 合力为零），再对水平方向做受力分析，列出平衡方程。", "tip": "“静止就是受力平衡”，不要看到“有拉力”就以为摩擦力一定存在方向问题。", "hard": "容易漏掉竖直方向的判断（重力与支持力也平衡）。"}, {"type": "sci", "level": "容易", "stem": "某溶液能使紫色石蕊试液变蓝，则该溶液：", "options": ["一定呈中性", "一定呈碱性", "一定是氢氧化钠溶液", "一定能使无色酚酞试液变蓝"], "answer": ["B"], "explain": "石蕊遇碱变蓝，故该溶液一定呈碱性，B 对。A 与变色规律矛盾。C 过于绝对，碳酸钠溶液等也呈碱性。D 错在酚酞遇碱变红而非变蓝，与石蕊变色规律不同。", "method": "记住指示剂变色规律：石蕊遇酸变红、遇碱变蓝；酚酞遇碱变红、遇酸不变色。", "tip": "“碱性溶液”不等于“某一种具体的碱”，别把结论收紧成某个具体物质。", "hard": "多个选项看似都对，要抓住题目问的“一定”与“直接对应”。"}, {"type": "sci", "level": "中等", "stem": "把一盆绿色植物放在黑暗处一昼夜后，用黑纸片把其中一片叶的一部分上下两面都遮盖起来，然后移到阳光下照射几小时，再取下该叶片脱色、漂洗、滴加碘液。结果是：", "options": ["遮盖部分不变蓝，未遮盖部分变蓝", "遮盖部分变蓝，未遮盖部分不变蓝", "整片叶都变蓝", "整片叶都不变蓝"], "answer": ["A"], "explain": "暗处理耗尽淀粉后，只有见光部分能进行光合作用制造淀粉，遇碘变蓝；遮光部分无光不能光合作用，无淀粉，不变蓝。故 A 对。", "method": "抓住实验变量是“光”，见光处才有光合作用产物（淀粉），淀粉遇碘变蓝。", "tip": "暗处理一昼夜是为了耗尽原有淀粉，这一步忘掉会误判。", "hard": "区分“光合作用产物淀粉”与“呼吸作用消耗有机物”。"}, {"type": "sci", "level": "中等", "stem": "把一根筷子斜插入盛水的碗中，从水面上方看去，水下部分好像“折断”并向上弯折。下列现象成因与之相同的是：", "options": ["用平面镜看到自己的像", "岸边看到水中的鱼比实际位置浅", "日食的形成", "手影游戏"], "answer": ["B"], "explain": "筷子“折断”是光从水射入空气时发生折射造成的。看到水中的鱼比实际浅同样是由光的折射引起，B 对。A 是平面镜反射（成像）；C、D 都属于光的直线传播形成影/食。", "method": "先判断现象类属：反射（镜面/成像）、折射（跨介质看物体）、直线传播（影/食/小孔成像）。", "tip": "“插入水中变弯”“池水变浅”“鱼的实际位置”都是折射。", "hard": "“看水中的鱼”是看物体（折射），而“水面映出天空”是反射，勿混。"}, {"type": "math", "level": "中等", "stem": "一项工程，甲单独做需 12 天，乙单独做需 18 天。两人合作完成这项工程，中途甲休息了 3 天，乙一直没有休息。问完成这项工程共用多少天？", "options": ["8 天", "9 天", "10 天", "11 天"], "answer": ["B"], "explain": "设工程总量为 36（12 与 18 的最小公倍数），则甲每天做 3，乙每天做 2。设共用了 T 天，乙工作 T 天，甲工作 T−3 天，有 3(T−3)+2T=36，即 5T−9=36，T=9。故选 B。", "method": "赋值法：把总量赋成两人单独完成时间的最小公倍数，求出各自效率，再按“谁休了几天”列方程。", "tip": "别把总量当 1 直接算效率，赋整数值更快且不易错。", "hard": "甲休息时乙仍在做功，这部分工作量容易算漏。"}, {"type": "math", "level": "容易", "stem": "甲、乙两地相距 300 千米。一辆汽车从甲地开往乙地，去时速度为 60 千米/小时，返回时速度为 50 千米/小时，则汽车往返的平均速度为：", "options": ["55 千米/小时", "53 千米/小时", "54.5 千米/小时", "60 千米/小时"], "answer": ["C"], "explain": "去时耗时 300÷60=5 小时，返回耗时 300÷50=6 小时，总路程 600 千米、总时间 11 小时，平均速度=600÷11≈54.5 千米/小时，C 对。注意平均速度不是速度的简单平均（那是 55，对应 A）。", "method": "往返平均速度 = 总路程 ÷ 总时间 = 2v₁v₂/(v₁+v₂)，切忌直接把两个速度相加除以 2。", "tip": "“平均速度”永远是总路程÷总时间；“速度的算术平均”是常见陷阱。", "hard": "若把 600÷11 粗算成 55，就会误选 A。"}, {"type": "math", "level": "容易", "stem": "把 200 克质量分数为 20% 的盐水与 300 克质量分数为 5% 的盐水混合，混合后盐水的质量分数约为：", "options": ["10%", "12.5%", "15%", "11%"], "answer": ["D"], "explain": "溶质总量=200×20%+300×5%=40+15=55 克，溶液总量=200+300=500 克，质量分数=55÷500=11%，D 对。", "method": "抓住“溶质守恒、质量相加”：分别算出各部分溶质，除以总质量。", "tip": "不要用 20% 和 5% 直接取中间值（12.5%），那是等质量混合才成立。", "hard": "两杯质量不同，混合后偏向质量大的那一杯的浓度。"}, {"type": "logic", "level": "中等", "stem": "晕轮效应是指在人际知觉中形成的以点概面、以偏概全的主观印象，即根据对象某一方面的突出特征而推断其其他方面。根据上述定义，下列属于晕轮效应的是：", "options": ["小张因为同事小李平时总是面带笑容，就觉得小李的工作能力也一定很强", "老师根据平时的多次观察和成绩记录，综合评定学生的学期等级", "公司按照统一的绩效考核指标，逐项给每位员工打分", "医生根据化验单上多项检查指标，综合判断患者的病情"], "answer": ["A"], "explain": "A 中仅凭“爱笑”这一突出特征，就推断出“工作能力强”，属于以点概面，符合定义。B、C、D 都是依据多个方面的信息做综合判断，不是以偏概全。故选 A。", "method": "定义判断抓“要件”：①基于某一突出特征 ②据此推断其他无关方面。两要件同时满足才符合。", "tip": "凡出现“综合评定／多项指标／逐项打分”等字眼的，一般是有依据的多维判断，不属于以偏概全。", "hard": "容易把“凭单一证据下结论”与“以某一特征推断其他方面”混为一谈。"}, {"type": "logic", "level": "中等", "stem": "厨师∶菜谱∶烹饪。下列选项中，与这组词在逻辑关系上最为贴近、相似或匹配的是：", "options": ["演员∶剧本∶表演", "观众∶电影∶影院", "学生∶课本∶考试", "病人∶药品∶医院"], "answer": ["A"], "explain": "题干关系：厨师依据菜谱这一“依据”来进行烹饪这一“活动”。A 中演员依据剧本来进行表演，关系一致。B 观众看电影的场所是影院，不符合；C 学生用课本但不是为了“考试”这一活动；D 病人用药品但“医院”是场所。故选 A。", "method": "类比先定“造句式”关系：把三词连成一句话，再拿同样句式去套选项。", "tip": "注意区分“依据（工具）关系”和“场所关系”，不要被表面词性带偏。", "hard": "多个选项都含“人+物+活动”字样，必须逐句核对关系是否一致。"}, {"type": "logic", "level": "容易", "stem": "所有优秀的运动员都经过刻苦训练。小刘经过了刻苦训练。由此可以推出：", "options": ["小刘一定是优秀运动员", "小刘一定不是优秀运动员", "小刘可能是优秀运动员", "优秀运动员都不需要刻苦训练"], "answer": ["C"], "explain": "“优秀运动员 → 刻苦训练”成立，但反过来“刻苦训练 → 优秀运动员”不一定成立。小刘满足后件（刻苦训练），只能推出他“可能”是优秀运动员，不能确定。故选 C。", "method": "记住充分条件推理规则：肯前必肯后，否后必否前；肯后、否前都不能推出确定结论。", "tip": "“所有 A 都 B”只能推出“非 B 非 A”，不能推出“B 则 A”。", "hard": "看到“经过了刻苦训练”就顺着条件倒推，是这类题最常见的错法。"}, {"type": "fig", "imgs": ["data/figs/figq_009_1.png", "data/figs/figq_009_2.png"], "stem": "从所给的四个选项中，选择最合适的一个填入问号处，使之呈现一定的规律性：", "options": ["", "", "", ""], "answer": ["C"], "explain": "竖排依次顺时针旋转90°。"}, {"type": "fig", "imgs": ["data/figs/figq_010_1.png"], "stem": "问号处应当是：", "options": ["", "", "", ""], "answer": ["D"], "explain": "前面三个图，图一加图二是图三（图一平移到图二中间的位置）。后三个图也是一样的道理，图一加图二是图三。只有选项D符合，所以答案选D。"}]}, {"set": 7, "date": "2026-10-13", "session": "am", "title": "行测加练 · 科学推理 + 数量关系 + 判断推理（第 7 批）", "items": [{"type": "sci", "level": "容易", "stem": "把一根筷子斜插入盛水的玻璃杯中，从侧面看，筷子好像在水面处“折断”了，且水下部分看起来变浅。关于这一现象，下列说法正确的是：", "options": ["光从水中斜射入空气时发生了反射", "光从水中斜射入空气发生折射，折射角小于入射角", "光从水中斜射入空气发生折射，折射角大于入射角", "这是光的直线传播造成的"], "answer": ["C"], "explain": "我们看到水下部分，是水中物体反射的光从水斜射入空气后进入眼睛；在界面处发生折射，因空气的折射率小于水，光从光密介质进入光疏介质，折射光线偏离法线，折射角大于入射角，人眼逆着折射光线看过去，物体像的位置比实际位置偏高，故“变浅”。A 说的是反射，与“变浅”无关；B 把折射角与入射角的大小关系说反了；D 属于光的直线传播（如影子、小孔成像），不是折射现象。", "method": "记住“光疏/光密介质”判断法：光从光密（水）入光疏（空气），折射角＞入射角，像偏高（变浅）；反过来从空气入水则折射角＜入射角。", "tip": "别把“反射”和“折射”混为一谈，也要注意方向：水中看空气与空气看水中，折射角大小关系正好相反。"}, {"type": "sci", "level": "容易", "stem": "一个物体在水平地面上做匀速直线运动，下列说法正确的是：", "options": ["物体不受任何力的作用", "物体所受的牵引力大于摩擦力", "物体所受的牵引力等于摩擦力，合力为零", "物体受到的合力方向一定与运动方向相同"], "answer": ["C"], "explain": "匀速直线运动属于平衡状态，物体所受合外力为零。水平方向上牵引力与摩擦力是一对平衡力，大小相等、方向相反，故 C 正确。A 错，不受力只是理想化情形，实际存在牵引力与摩擦力；B 错，若牵引力大于摩擦力物体将加速而不再匀速；D 错，合力为零时没有确定的合力方向。", "method": "看到“静止或匀速直线运动”立刻判定为平衡状态，合外力为零，方向相反的两个力必然等大。", "tip": "关键在“匀速”二字，很多人只盯着力的大小而忘了合力为零这个本质。"}, {"type": "sci", "level": "中等", "stem": "某同学用 pH 试纸测某溶液的 pH，测得结果为 3。下列说法正确的是：", "options": ["该溶液一定是盐酸", "该溶液显酸性，且 pH 越小酸性越强", "该溶液能使酚酞试液变红", "该溶液加水稀释后，pH 会增大到 7 以上"], "answer": ["B"], "explain": "pH＜7 显酸性，且 pH 越小酸性越强，B 正确。pH=3 只能说明溶液显酸性，酸有很多种（硫酸、醋酸等），无法断定就是盐酸，A 错。酚酞遇酸不变色、遇碱变红，C 错。酸性溶液加水稀释时 pH 会向 7 靠近，但无论怎样稀释都不会超过 7，D 错。", "method": "牢记 pH 判据：＜7 酸性、=7 中性、＞7 碱性，数值越远离 7 酸碱性越强。", "tip": "“稀释后 pH 一定升到 7 以上”是典型错项，无限稀释也只是无限接近 7。"}, {"type": "sci", "level": "中等", "stem": "下列关于植物光合作用和呼吸作用的说法，正确的是：", "options": ["光合作用只在白天进行，呼吸作用只在夜间进行", "光合作用消耗氧气，产生二氧化碳", "光合作用在叶绿体中进行，呼吸作用在活细胞内均可进行", "植物白天不进行呼吸作用"], "answer": ["C"], "explain": "光合作用在叶绿体中进行、需要光照；呼吸作用在活细胞的线粒体（细胞质）中进行，昼夜不停，故 C 正确。A 错在“呼吸作用只在夜间进行”；B 把两者物质变化弄反了，光合作用吸收二氧化碳、放出氧气；D 错，白天植物既进行光合作用也进行呼吸作用。", "method": "用两句话记：光合作用“吃”二氧化碳、“吐”氧气，只在有光时进行；呼吸作用“吃”氧气、“吐”二氧化碳，昼夜不停。", "tip": "常见坑是把“呼吸作用只在夜间”“白天只进行光合作用”当成正确说法。"}, {"type": "math", "level": "容易", "stem": "一项工程，甲单独做 10 天完成，乙单独做 15 天完成。两人合作，几天可以完成？", "options": ["5 天", "6 天", "7 天", "8 天"], "answer": ["B"], "method": "赋值法。设总工程量为 10 和 15 的最小公倍数 30，则甲效率为 30÷10=3，乙效率为 30÷15=2，合作效率为 5，时间＝30÷5=6 天。", "explain": "设总工程量为 30，甲每天完成 30/10=3，乙每天完成 30/15=2，两人合作每天完成 3+2=5，故需要 30÷5=6 天，选 B。", "tip": "不要直接把 10 与 15 相加再除以 2；工程问题优先把总量赋值为各时间的最小公倍数。"}, {"type": "math", "level": "中等", "stem": "甲、乙两车分别从 A、B 两地同时出发相向而行，甲车速度 60 千米/时，乙车速度 40 千米/时，两地相距 200 千米。两车相遇时，甲车行驶了多少千米？", "options": ["80 千米", "100 千米", "120 千米", "130 千米"], "answer": ["C"], "method": "相遇问题：相遇时间＝路程和÷速度和，再由各自速度×时间求各自路程。也可用比例法：路程比＝速度比＝60∶40＝3∶2，全程 5 份，甲占 3 份。", "explain": "速度和为 60+40=100（千米/时），相遇时间＝200÷100=2 小时，甲车行 60×2=120 千米。用比例法验证：甲∶乙＝3∶2，甲占全程的 3/5，200×3/5=120 千米，选 C。", "tip": "比例法最快，但要注意甲占的是 3/5 而不是 2/5，别把快慢车的份额弄反。"}, {"type": "math", "level": "中等", "stem": "有浓度为 20% 的酒精溶液 300 克，要使其浓度变为 15%，需要加水多少克？", "options": ["60 克", "80 克", "100 克", "120 克"], "answer": ["C"], "method": "抓住“溶质不变”：先求原溶质，再用水后浓度反推溶液总量，两者之差即为加水量。", "explain": "原溶液中酒精＝300×20%=60 克。加水后溶质仍为 60 克，占总量的 15%，则加水后溶液总量＝60÷15%=400 克，故需加水 400−300=100 克，选 C。", "tip": "浓度＝溶质÷溶液（不是÷水）；加水时溶质不变、溶液变多，别把分母写错。"}, {"type": "logic", "level": "容易", "stem": "律师∶法庭。下列各组词中与题干逻辑关系最为相似的是：", "options": ["医生∶医院", "教师∶学生", "农民∶土地", "司机∶汽车"], "answer": ["A"], "explain": "题干中律师的职业活动场所是法庭，二者是“职业与工作场所”的关系。医生的工作场所是医院，A 与题干关系一致。B 教师与学生是教育者与教育对象的关系；C 农民对土地更接近劳动对象/依托；D 司机使用汽车是工具与操作者的关系。关系类型最贴切的只有 A。", "method": "类比推理先定关系类型（场所、工具、对象、种属、并列……），再逐项比对，选关系类型完全一致的那一项。", "tip": "“职业∶场所”要盯住“工作场所”，别被 C 的“土地”带偏成劳动对象。"}, {"type": "logic", "level": "中等", "stem": "破窗效应：如果有人打坏了一幢建筑物的窗户玻璃，而这扇窗户又得不到及时的维修，别人就可能受到某些暗示性的纵容，去打烂更多的窗户。也就是说，环境中的不良现象如果被放任存在，会诱使人们仿效，甚至变本加厉。根据上述定义，下列属于破窗效应的是：", "options": ["小区里有一处垃圾长期无人清理，很快角落里堆满了居民乱扔的垃圾", "老师批评了迟到的学生，此后班里的迟到现象明显减少", "商场开展打折促销活动，顾客纷纷前来购买商品", "天气转凉，患感冒的人逐渐增多"], "answer": ["A"], "explain": "A 中“垃圾长期无人清理”正是被放任的不良现象，随后诱使更多人乱扔垃圾，符合“放任→仿效→加剧”，属于破窗效应。B 是及时纠正后情况变好，与“放任”方向相反；C 是促销吸引顾客，与不良现象无关；D 属自然现象，没有仿效效应。", "method": "定义判断抓关键点：①不良现象被放任存在 ②他人仿效、加剧。逐项核对关键点是否齐全。", "tip": "干扰项常给“及时处理使情况变好”，与定义方向正好相反，注意别选。"}, {"type": "logic", "level": "中等", "stem": "已知“如果今天下雨，那么运动会取消”。今天运动会没有取消。由此可以推出：", "options": ["今天下雨了", "今天没下雨", "今天可能下雨", "无法确定今天是否下雨"], "answer": ["B"], "explain": "原命题“下雨→取消”的逆否命题是“不取消→不下雨”，两者等价。现在“没有取消”成立，根据逆否命题可必然推出“今天没下雨”，选 B。A 与结论矛盾；C、D 认为结论不确定，但由逆否推理可唯一确定，故排除。", "method": "充分条件假言命题“A→B”等价于“¬B→¬A”。见到后件的否定，就直接用逆否推理得前件的否定。", "tip": "不要用“否定前件”或“肯定后件”去乱推，这两种方式都得不出必然结论。"}, {"type": "fig", "imgs": ["data/figs/figq_013_1.png", "data/figs/figq_013_2.png"], "src": "", "cat": "", "fmt": "", "stem": "问号处应当是：", "options": ["", "", "", ""], "answer": ["D"], "explain": "第一图中，图一减去图二的一半等于图三；第二图中图一减去图二的一半等于D。", "trap": ""}, {"type": "fig", "imgs": ["data/figs/figq_014_1.png"], "src": "", "cat": "", "fmt": "", "stem": "下列哪一个图形是特殊的？", "options": ["", "", "", ""], "answer": ["C"], "explain": "相邻两个图形大小不一，其它选项都有相同的相邻情况。", "trap": ""}]}, {"set": 8, "date": "2026-10-14", "session": "am", "title": "行测加练 · 科学推理 + 数量关系 + 判断推理（第 8 批）", "items": [{"type": "sci", "level": "容易", "stem": "一辆汽车在平直公路上匀速行驶，下列说法正确的是：", "options": ["汽车受到的牵引力与阻力是一对平衡力", "汽车不受任何力的作用", "汽车受到的牵引力大于阻力", "汽车受到的重力与牵引力是一对平衡力"], "answer": ["A"], "explain": "汽车匀速直线行驶，处于平衡状态，受到的合力为零。水平方向上牵引力与阻力大小相等、方向相反、作用在同一直线上，是一对平衡力，A 正确。B 错，汽车一定受力；C 若牵引力大于阻力则汽车会加速；D 重力与支持力才是一对平衡力，牵引力与之方向垂直，不成对。", "method": "看到“匀速直线运动”或“静止”，先判定物体受平衡力（合力为零），再找同一直线上大小相等、方向相反的一对力。", "tip": "运动不需要合外力维持；匀速、静止都对应平衡力。", "hard": ""}, {"type": "sci", "level": "中等", "stem": "用扇子扇燃着的蜡烛，火焰会熄灭；而扇炉火时却越扇越旺。蜡烛熄灭的原因是：", "options": ["隔绝了氧气", "移走了可燃物", "使温度降到了着火点以下", "增大了氧气的浓度"], "answer": ["C"], "explain": "扇蜡烛时，气流带走大量热量，使石蜡温度降到着火点以下，燃烧停止，C 正确。扇炉火时气流带走的少量热量被炉火自身补充，同时补充了氧气，所以越烧越旺。A、B 均与事实不符，D 只会助燃不会灭火。", "method": "燃烧需同时满足三个条件：可燃物、氧气、温度达到着火点；灭火只需破坏其中任意一个。", "tip": "判断灭火原理要对号入座：浇水降温、盖沙隔绝氧气、清走柴草移除可燃物。", "hard": ""}, {"type": "sci", "level": "容易", "stem": "关于绿色植物的光合作用与呼吸作用，下列说法正确的是：", "options": ["光合作用只在白天进行，呼吸作用只在夜晚进行", "光合作用制造有机物并释放氧气", "呼吸作用消耗氧气，但不产生任何能量", "光合作用和呼吸作用都在叶绿体中进行"], "answer": ["B"], "explain": "光合作用利用光能把二氧化碳和水合成有机物并释放氧气，B 正确。A 错，呼吸作用昼夜都进行；C 错，呼吸作用分解有机物、释放能量；D 错，呼吸作用主要在细胞质和线粒体中进行，叶绿体是光合作用的场所。", "method": "记两条线：光合作用“吸二氧化碳、放氧气、造有机物、需光”；呼吸作用“吸氧气、放二氧化碳、耗有机物、昼夜不停”。", "tip": "呼吸作用昼夜不停，别误以为只在夜晚进行。", "hard": ""}, {"type": "sci", "level": "中等", "stem": "关于声音的传播，下列说法正确的是：", "options": ["声音在真空中传播得最快", "声音在固体中传播一般比在空气中快", "只要物体振动，人耳就一定能听到声音", "声音在空气中的传播速度是 340 米/秒，且与温度无关"], "answer": ["B"], "explain": "声音的传播需要介质，一般在固体中最快、气体中最慢，B 正确。A 错，真空不能传声；C 错，能否听到还与振动频率是否在听觉范围（约 20~20000 赫兹）、响度大小有关；D 错，声速随温度升高而增大，340 米/秒是 15℃ 空气时的近似值。", "method": "声速比较：固体 > 液体 > 气体；真空不能传声。", "tip": "“振动就一定听得到”是常见陷阱——还要看频率和响度。", "hard": ""}, {"type": "math", "level": "容易", "stem": "一项工作，甲单独做需 10 天完成，乙单独做需 15 天完成。两人合作，需要多少天完成？", "options": ["5 天", "6 天", "6.5 天", "7.5 天"], "answer": ["B"], "explain": "赋值法：设工作总量为 10 和 15 的最小公倍数 30，则甲效率为 30÷10=3，乙效率为 30÷15=2，合作效率为 5，所需时间为 30÷5=6（天），选 B。", "method": "工程问题首选赋值法：把总量设为工期的公倍数，效率=总量÷时间；合作时间=总量÷效率之和。", "tip": "别把两人的时间直接相加（10+15=25）或取平均，那是常见错算。", "hard": ""}, {"type": "math", "level": "中等", "stem": "一件商品成本 80 元，标价 120 元，商家按标价打八折出售，则利润率是多少？", "options": ["16%", "20%", "25%", "33.3%"], "answer": ["B"], "explain": "售价=120×0.8=96 元，利润=96−80=16 元，利润率=利润÷成本=16÷80=20%，选 B。", "method": "利润率=（售价−成本）÷成本；先算实际售价（标价×折扣），再套公式。", "tip": "注意利润率的分母是“成本”不是“售价”，用 16÷96≈16.7% 是典型错算。", "hard": ""}, {"type": "math", "level": "中等", "stem": "从 5 名同学中选出 3 名，并让他们排成一排照相，共有多少种不同的排法？", "options": ["10 种", "20 种", "60 种", "120 种"], "answer": ["C"], "explain": "“选出 3 名并排队”与顺序有关，是排列问题：A(5,3)=5×4×3=60（种），选 C。若只选不排则是组合 C(5,3)=10 种。", "method": "先判断“与顺序有关吗”：有关→排列 A(n,m)；无关→组合 C(n,m)。", "tip": "“照相、排队、派岗位”都算排列，别误用组合。", "hard": ""}, {"type": "logic", "level": "中等", "stem": "晕轮效应：指人们对他人的认知判断首先根据个人的好恶得出，然后再从这个判断推论出认知对象的其他品质的现象。根据上述定义，下列属于晕轮效应的是：", "options": ["因为小李长得帅气，同事们就认为他的工作能力也一定很强", "老师根据小明平时作业和考试的表现，判断他这次能考好", "消费者因为某品牌广告投放多，觉得它的产品质量更好", "小王因为一次工作失误受到上司批评"], "answer": ["A"], "explain": "A 中同事由“长得帅气”这一好恶印象，推出“能力也强”，符合“先凭好恶下判断，再由该判断推论其他品质”，属于晕轮效应。B 是基于实际表现的合理推断；C 是受广告影响，不属于对“人”的认知；D 是对具体行为的评价，均不符合定义。", "method": "定义判断抓“要件”：①对象是“人”②先凭个人好恶形成印象③再据此推出其他品质。逐项比对要件。", "tip": "“因为外表好而推断能力强/人品好”是晕轮效应的典型表述。", "hard": ""}, {"type": "logic", "level": "容易", "stem": "蜜蜂：蜂蜜。请从选项中选出与这对关系最为相似的一项：", "options": ["树叶：树木", "蚕：蚕丝", "茧：蛾", "花朵：花蜜"], "answer": ["B"], "explain": "蜜蜂产出蜂蜜，是“生物与其所产之物”的对应关系；蚕产出蚕丝，关系与之最相似，选 B。A 是部分与整体，C 是发育阶段（茧化蛾），D 是采食（花朵提供花蜜），均不相同。", "method": "类比推理先确定题干两词的逻辑关系（这里是“产出关系”），再找关系一致的一项。", "tip": "“蜜蜂产蜜”对“蚕产丝”，是常见的产出关系类比。", "hard": ""}, {"type": "logic", "level": "中等", "stem": "已知：所有喜欢阅读的人都善于思考；小李善于思考。由此可以推出：", "options": ["小李喜欢阅读", "小李不喜欢阅读", "小李很可能喜欢阅读", "无法确定小李是否喜欢阅读"], "answer": ["D"], "explain": "“所有喜欢阅读的人都善于思考”表示：喜欢阅读 → 善于思考。小李“善于思考”是肯定了后件，而肯定后件不能肯定前件，所以不能推出小李是否喜欢阅读，选 D。", "method": "记住推理规则：肯前必肯后、否后必否前；肯后、否前都得不出确定结论。", "tip": "“所有 A 都是 B，某人是 B”推不出“某人是 A”——这是必要条件被误当成充分条件。", "hard": ""}, {"type": "fig", "imgs": ["data/figs/figq_019_1.png", "data/figs/figq_019_2.png"], "stem": "根据以上图形的规律，下一个图形应该是：", "options": ["", "", "", ""], "answer": ["D"], "explain": "箭头依次顺时针旋转 90°。"}, {"type": "fig", "imgs": ["data/figs/figq_020_1.png"], "stem": "找出下列图形中不同于其他图形的一项：", "options": ["", "", "", ""], "answer": ["A"], "explain": "图 234 中黑球数量均为 7。"}]}, {"set": 9, "date": "2026-10-14", "session": "pm", "title": "行测加练 · 科学推理 + 数量关系 + 判断推理（第 9 批）", "items": [{"type": "sci", "level": "容易", "stem": "关于液体内部的压强，下列说法正确的是：", "options": ["液体压强随深度的增加而增大", "液体压强与液体的密度无关", "液体内部同一深度，各方向的压强不相等", "液体压强只与容器的形状有关"], "answer": ["A"], "explain": "由 p=ρgh 可知，液体压强随深度 h 增加而增大，A 正确。B 错，密度 ρ 越大压强越大；C 错，同一深度各方向压强相等；D 错，液体压强与容器形状无关，只与液体密度和深度有关。", "method": "液体压强公式 p=ρgh：只看“密度”和“深度”两个变量，与容器形状、液体总量无关。", "tip": "大坝下宽上窄、潜水服抗压，都是“深度越深压强越大”的体现。", "hard": ""}, {"type": "sci", "level": "中等", "stem": "关于溶液的 pH，下列说法正确的是：", "options": ["常温下 pH<7 的溶液一定显酸性", "pH 越小，溶液的酸性越弱", "pH=7 的溶液一定是纯水", "用 pH 试纸可以准确测得某溶液 pH=5.6"], "answer": ["A"], "explain": "常温下 pH<7 显酸性，A 正确。B 错，pH 越小酸性越强；C 错，pH=7 只表示中性，还可能是氯化钠等中性盐溶液；D 错，pH 试纸只能读到整数，不能读出 5.6。", "method": "pH<7 酸性、=7 中性、>7 碱性（常温）；试纸读数取整，精密测量用 pH 计。", "tip": "“pH=7 就是纯水”是常见陷阱，中性盐溶液的 pH 也为 7。", "hard": ""}, {"type": "sci", "level": "容易", "stem": "关于遗传与变异，下列说法正确的是：", "options": ["人的性别由常染色体决定", "基因是控制生物性状的基本单位", "只有显性基因才能遗传给后代", "环境不会影响生物的性状"], "answer": ["B"], "explain": "基因是控制生物性状的基本单位，B 正确。A 错，人的性别由性染色体决定；C 错，隐性基因同样能遗传，只是不一定表现出来；D 错，生物性状是基因与环境共同作用的结果。", "method": "抓住“基因—性状”这一主线：基因控制性状，但性状表现还受环境影响。", "tip": "“性别由常染色体决定”是典型错项，人的性别由 X、Y 性染色体决定。", "hard": ""}, {"type": "sci", "level": "中等", "stem": "关于热传递，下列说法正确的是：", "options": ["热量总是自发地从低温物体传给高温物体", "热传递的三种方式是传导、对流和辐射", "热传递能改变物体的内能，而做功不能", "只要两物体内能不同，就一定会发生热传递"], "answer": ["B"], "explain": "热传递的三种方式是传导、对流和辐射，B 正确。A 错，热量自发地从高温物体传到低温物体；C 错，做功和热传递都能改变内能；D 错，发生热传递的条件是两物体存在温度差，而非内能不同。", "method": "热传递的条件是“温度差”，方向是“高温→低温”，方式是“传导、对流、辐射”。", "tip": "“内能不同就热传递”是陷阱，关键看“温度”是否有差别。", "hard": ""}, {"type": "math", "level": "中等", "stem": "现有含盐 20% 的盐水 200 克，要使其含盐量降为 10%，需要加水多少克？", "options": ["100 克", "150 克", "200 克", "400 克"], "answer": ["C"], "explain": "加水前后盐的质量不变：200×20%=40 克。要使含盐量为 10%，则盐水总质量应为 40÷10%=400 克，故需加水 400−200=200 克，选 C。", "method": "稀释问题抓“溶质不变”：先算溶质质量，再由目标浓度反推溶液总质量，差额即为加水量。", "tip": "别按“浓度降一半、水加一倍”直接猜 200——只有原溶液刚好 200 克时才好巧，稳妥用溶质守恒。", "hard": ""}, {"type": "math", "level": "中等", "stem": "甲以每小时 5 公里的速度步行，出发 2 小时后，乙骑车以每小时 15 公里的速度沿同一路线追赶。乙追上甲需要多少小时？", "options": ["0.5 小时", "1 小时", "1.5 小时", "2 小时"], "answer": ["B"], "explain": "乙出发时，甲已领先 5×2=10 公里；两人速度差为 15−5=10 公里/小时。追及时间=追及距离÷速度差=10÷10=1（小时），选 B。", "method": "追及问题公式：追及时间=追及距离（领先路程）÷速度差。", "tip": "别忘了先算“出发时已拉开的距离”，直接用 10÷15 是典型错算。", "hard": ""}, {"type": "math", "level": "容易", "stem": "5 个数的平均数是 12，去掉其中一个数后，剩下 4 个数的平均数是 11。去掉的那个数是多少？", "options": ["8", "11", "16", "20"], "answer": ["C"], "explain": "5 个数总和为 12×5=60，剩下 4 个数总和为 11×4=44，去掉的数为 60−44=16，选 C。", "method": "平均数问题用“总和=平均数×个数”：分别算整体和部分的总和，作差即可。", "tip": "去掉的数通常大于原平均数（因为剩下的平均数变小了），可用此快速排除偏小的选项。", "hard": ""}, {"type": "logic", "level": "中等", "stem": "沉没成本：指已经付出且无论如何都无法收回的支出。根据上述定义，下列属于沉没成本的是：", "options": ["小张已买好、无法退票的电影票钱", "小李计划明年买车的一笔预算", "小王这个月还没交的房租", "小赵打算周末去旅游的交通费"], "answer": ["A"], "explain": "电影票钱已经付出且无法退票收回，属于沉没成本，A 正确。B、C、D 都尚未实际支出，可以决定是否花，均不属于“已经付出且无法收回”。", "method": "定义判断抓要件：①已经付出 ②无法收回。逐项比对，只要“还没花”或“能收回”就排除。", "tip": "判断沉没成本的关键是“已经付出 + 收不回”，未发生的支出不算。", "hard": ""}, {"type": "logic", "level": "容易", "stem": "医生：手术刀。请从选项中选出与这对关系最为相似的一项：", "options": ["读者：图书馆", "作家：钢笔", "出版社：图书", "灵感：作家"], "answer": ["B"], "explain": "手术刀是医生使用的工具，是“职业与其工具”的对应关系；钢笔是作家写作的工具，关系最相似，选 B。A 是人物与场所，C 是机构与产品，D 是抽象物与人物，均不相同。", "method": "类比推理先定关系（这里为“工具关系”），再看选项中哪个关系一致。", "tip": "看到“职业：工具”的类比，优先找“某职业 + 该职业所用工具”的选项。", "hard": ""}, {"type": "logic", "level": "中等", "stem": "已知：如果下雨，那么地面会湿。现在观察到地面湿了，由此可以推出：", "options": ["一定下过雨", "一定没有下雨", "可能下过雨，也可能因其他原因而湿", "下雨与地面湿没有关系"], "answer": ["C"], "explain": "“如果下雨，那么地面湿”表示：下雨 → 地面湿。现在“地面湿”是肯定了后件，而肯定后件不能肯定前件——地面湿也可能由洒水、漏水等原因造成，因此只能推出“可能下过雨”，选 C。", "method": "牢记“肯前必肯后、否后必否前；肯后、否前都不确定”，遇到“后件成立”要警惕陷阱。", "tip": "由“地面湿”不能断定“下过雨”，这是把充分条件当成了必要条件。", "hard": ""}, {"type": "fig", "imgs": ["data/figs/figq_021_1.png", "data/figs/figq_021_2.png"], "stem": "接下来的图形应该是：", "options": ["", "", "", ""], "answer": ["D"], "explain": "图一二三四均为封闭图形排除 B 项，且大图形与小图形紧邻排除 A、C 项。"}, {"type": "fig", "imgs": ["data/figs/figq_022_1.png", "data/figs/figq_022_2.png"], "stem": "接下来的图形应该是：", "options": ["", "", "", ""], "answer": ["D"], "explain": "间隔的黑块白块组成完整图形，如 1 和 2 组成完整图形。"}]}, {"set": 10, "date": "2026-10-15", "session": "am", "title": "行测加练 · 科学推理 + 数量关系 + 判断推理（第 10 批）", "items": [{"type": "sci", "level": "容易", "stem": "关于串联电路和并联电路，下列说法正确的是：", "options": ["串联电路中各处的电流都相等", "并联电路中各支路的电压之和等于电源电压", "串联电路中各用电器两端的电压一定相等", "并联电路中干路电流一定小于任一支路的电流"], "answer": ["A"], "explain": "串联电路中电流处处相等，A 正确。B 错，并联各支路电压都等于电源电压（不是相加）；C 错，串联时各用电器电压与电阻成正比，不一定相等；D 错，干路电流等于各支路电流之和，大于任一支路电流。", "method": "记两个口诀：串联“电流相等、电压按电阻分配”，并联“电压相等、干路电流等于各支路之和”。", "tip": "“串流并压”——串联看电流相同，并联看电压相同，判断时先分清电路连接方式。", "hard": ""}, {"type": "sci", "level": "中等", "stem": "关于凸透镜成像规律，下列说法正确的是：", "options": ["物体放在焦点以内时，成倒立、放大的实像", "照相机成像时，物体应位于二倍焦距以外", "投影仪成像时，物体应位于焦点以内", "凸透镜成实像时，物距越小，成的像越小"], "answer": ["B"], "explain": "照相机物距 u>2f，成倒立、缩小的实像，B 正确。A 错，物在焦点以内成正立、放大的虚像；C 错，投影仪 f<u<2f，成倒立、放大的实像；D 错，成实像时物距越小、像距越大、像越大。", "method": "“一倍焦距分虚实、二倍焦距分大小”：u>2f 缩小实像（照相机）、f<u<2f 放大实像（投影仪）、u<f 放大虚像（放大镜）。", "tip": "“物近像远像变大”只适用于成实像的情形，别套到虚像上。", "hard": ""}, {"type": "sci", "level": "容易", "stem": "关于增大或减小压强，下列说法正确的是：", "options": ["书包背带做得较宽，是为了增大压强", "刀刃磨得很薄，是为了减小压强", "载重汽车的轮胎又多又宽，是为了减小对地面的压强", "图钉尖做得很尖，是为了减小对墙面的压强"], "answer": ["C"], "explain": "由 p=F/S 可知，受力面积越大压强越小。轮胎又多又宽增大了受力面积，减小对地面的压强，C 正确。A 错，背带宽是减小压强；B、D 错，刀薄、钉尖都是减小受力面积、增大压强。", "method": "压强 p=F/S：判断压强大小就看压力 F 和受力面积 S，面积大→压强小，面积小→压强大。", "tip": "“尖、薄、窄”一般是为了增大压强；“宽、大、多”一般是为了减小压强。", "hard": ""}, {"type": "sci", "level": "中等", "stem": "关于生态系统的组成和能量流动，下列说法正确的是：", "options": ["生态系统只由生产者、消费者和分解者组成", "生态系统中能量沿食物链逐级递减", "食物链通常从消费者开始", "分解者能把无机物合成有机物供植物利用"], "answer": ["B"], "explain": "能量在食物链中单向流动、逐级递减，B 正确。A 错，生态系统还包括阳光、空气、水等非生物的物质和能量；C 错，食物链从生产者（绿色植物）开始；D 错，分解者把动植物遗体中的有机物分解为无机物，合成有机物的是生产者。", "method": "生态题抓三句：食物链从生产者起；能量单向流动、逐级递减；分解者把有机物分解为无机物。", "tip": "生态系统=生物部分（生产者/消费者/分解者）+ 非生物部分，别漏了阳光、水、空气等。", "hard": ""}, {"type": "math", "level": "容易", "stem": "在一条长 100 米的路的一侧栽树，每隔 5 米栽一棵（两端都要栽），一共要栽多少棵？", "options": ["19 棵", "20 棵", "21 棵", "22 棵"], "answer": ["C"], "explain": "两端都栽时棵数=间隔数+1。间隔数=100÷5=20，故要栽 20+1=21 棵，选 C。", "method": "植树问题：两端都栽→棵数=段数+1；只栽一端→棵数=段数；两端都不栽→棵数=段数−1。", "tip": "先分清“两端栽不栽”再套公式；100÷5=20 只是间隔数，别直接当成棵数。", "hard": ""}, {"type": "math", "level": "容易", "stem": "袋中有 3 个红球和 2 个白球，除颜色外完全相同。从中任意摸出一个球，摸到红球的概率是多少？", "options": ["1/2", "2/5", "3/5", "3/2"], "answer": ["C"], "explain": "共有 3+2=5 个球，其中红球 3 个，摸到红球的概率=3/5，选 C。", "method": "古典概型：概率=符合条件的结果数 ÷ 全部等可能的结果数。", "tip": "概率一定在 0 和 1 之间，“3/2”大于 1 必错，可直接排除。", "hard": ""}, {"type": "math", "level": "中等", "stem": "笼子里有鸡和兔共 20 只，它们共有 56 条腿。兔子有多少只？", "options": ["6 只", "8 只", "10 只", "12 只"], "answer": ["B"], "explain": "假设全是鸡，则腿数为 2×20=40 条，实际多出 56−40=16 条；每把一只鸡换成兔多 2 条腿，故兔=16÷2=8 只，选 B。（方程法：4x+2(20−x)=56，解得 x=8。）", "method": "鸡兔同笼用“假设法”：假设全是鸡，求出比实际少的腿数，再除以“每换一只的差值”（鸡兔差 2 条腿）。", "tip": "假设法关键是“每换一只相差几条腿”，鸡换兔相差 2 条，别误算成 4 条。", "hard": ""}, {"type": "logic", "level": "中等", "stem": "羊群效应是指个体的行为容易受到多数人行为的影响，从而盲目跟从大众、放弃独立判断的现象。根据上述定义，下列属于羊群效应的是：", "options": ["小张学习了理财知识后，根据自己的风险承受能力选择了基金", "看到周围人都在抢购某款商品，小李原本不需要也跟风买了一件", "小王经过比较后选定了一家性价比更高的旅行社", "小赵坚持每天早起锻炼，不受他人影响"], "answer": ["B"], "explain": "B 中因他人抢购而盲目跟风，买了自己本不需要的东西，符合“受多数人影响、放弃独立判断”，正确。A、C 都是经过独立判断的自主选择；D 是坚持自我、不受他人影响，均不符合。", "method": "定义判断抓要件：①受多数人行为影响 ②盲目跟从而非独立判断。逐项核对，凡“自己思考过”的直接排除。", "tip": "“羊群效应”的核心是“盲目从众”，有独立判断的不算。", "hard": ""}, {"type": "logic", "level": "容易", "stem": "汽车：轮胎。请从选项中选出与这对关系最为相似的一项：", "options": ["学校：老师", "书本：封面", "农民：庄稼", "铅笔：作业"], "answer": ["B"], "explain": "轮胎是汽车的组成部分，属于“整体与部分”关系；封面是书本的组成部分，关系一致，选 B。A 是整体与其人员，C 是职业与劳动对象，D 是工具与用途，均不同。", "method": "类比先定关系：“整体—部分”“职业—工具”“种属”“因果”等，再找关系一致的选项。", "tip": "遇到“整体:部分”的题，注意排除“整体:人/单位”这类看似相关的关系。", "hard": ""}, {"type": "logic", "level": "中等", "stem": "已知：甲或者乙参加了昨天的会议（至少有一人参加）。经确认，甲没有参加。由此可以推出：", "options": ["乙一定参加了会议", "乙一定没有参加会议", "甲、乙都没有参加会议", "无法确定乙是否参加了会议"], "answer": ["A"], "explain": "“甲或乙参加”表示至少一人参加（相容选言命题）。现在甲没参加，否定其中一支，则另一支必真，即乙一定参加，选 A。", "method": "相容选言推理规则：“否定一部分，就要肯定另一部分”（否一推一）；由“肯定一支”不能推出另一支的真假。", "tip": "“或”表示至少一个，排除一支后剩下的必然成立，别把它当成“都可能不确定”。", "hard": ""}, {"type": "fig", "imgs": ["data/figs/figq_023_1.png", "data/figs/figq_023_2.png"], "stem": "接下来的图形应该是：", "options": ["", "", "", ""], "answer": ["A"], "explain": "三个图上都有＋号，×号，黑圆，白圆但是位置不相同。先来看＋号的位置，图一到图二＋号顺时针走了3个格，图二到图三顺时针＋号走了4个格，所以图四应该是在图三的基础上顺时针走5个格。再来看×号的位置，图一到图二×顺时针走了1个格，图二到图三×顺时针走了1个格，所以图四应该是在图三的基础上顺时针走1个格。看黑圆的位置，图一到图二顺时针走了6个格，图二到图三顺时针走了5个格，所以图四应该是在图三的基础上顺时针走了4个格。看白圆的位置，图一到图二顺时针走了2个格，图二到图三顺时针走了2个格，所以图四应该是在图三的基础上顺时针走2个格。只有选项A符合，所以选A。"}, {"type": "fig", "imgs": ["data/figs/figq_024_1.png", "data/figs/figq_024_2.png"], "stem": "问号处的图形应该是：", "options": ["", "", "", ""], "answer": ["A"], "explain": "每一行横着看，白+白=白，白+灰=灰，黑+白=灰，黑+黑=白，黑+灰=黑。"}]}, {"set": 11, "date": "2026-10-15", "session": "pm", "title": "行测加练 · 科学推理 + 数量关系 + 判断推理（第 11 批）", "items": [{"type": "sci", "level": "中等", "stem": "关于电压、电流和电阻，下列说法正确的是：", "options": ["导体两端的电压为零时，它的电阻也为零", "导体电阻的大小由它两端的电压和通过的电流共同决定", "同一导体两端的电压增大，通过它的电流也随之增大", "导体的电阻随通过它的电流增大而减小"], "answer": ["C"], "explain": "电阻一定时，电流与电压成正比，电压增大电流随之增大，C 正确。A 错，电阻是导体本身的性质，与有无电压无关；B 错，电阻由材料、长度、横截面积和温度决定，与电压、电流无关；D 错，电阻不随电流变化。", "method": "欧姆定律 I=U/R。牢记“电阻是导体本身的性质”，R=U/I 只是计算式，不是决定式。", "tip": "“电压为零电阻为零”是典型陷阱，电阻与导体两端有没有电压无关。", "hard": ""}, {"type": "sci", "level": "容易", "stem": "关于大气压强，下列说法正确的是：", "options": ["大气压强随海拔高度的升高而增大", "用吸管吸饮料，是利用大气压强把饮料压入嘴里", "马德堡半球实验第一次测出了大气压强的数值", "大气压强的大小与海拔高度、天气都没有关系"], "answer": ["B"], "explain": "吸饮料时先把吸管中的空气吸走，管内气压减小，外界大气压就把饮料压入口中，B 正确。A 错，海拔越高空气越稀薄，大气压越小；C 错，马德堡半球实验证明大气压的存在，首次测出大气压数值的是托里拆利实验；D 错，大气压随海拔和天气变化。", "method": "大气压题抓两点：“海拔越高气压越低”；“证明存在（马德堡半球）≠ 测出数值（托里拆利）”。", "tip": "高压锅、吸盘、吸管都利用大气压，但“托里拆利实验”才是测量大气压值的实验。", "hard": ""}, {"type": "sci", "level": "中等", "stem": "关于氧气和二氧化碳的性质与检验，下列说法正确的是：", "options": ["氧气能支持燃烧，可用带火星的木条来检验", "二氧化碳能使干燥的紫色石蕊纸花变红", "二氧化碳能使澄清石灰水变浑浊，说明二氧化碳显酸性", "氧气不易溶于水，所以水中几乎不含氧气"], "answer": ["A"], "explain": "氧气能支持燃烧，使带火星的木条复燃，这是检验氧气的常用方法，A 正确。B 错，二氧化碳本身不能使干燥石蕊纸花变红，只有与水反应生成碳酸后才显酸性；C 错，石灰水变浑浊是因为生成难溶的碳酸钙，不能说明二氧化碳本身显酸性；D 错，氧气虽不易溶于水，但水中仍溶有少量氧气，水生生物靠它呼吸。", "method": "气体检验口诀：氧气——带火星木条复燃；二氧化碳——使澄清石灰水变浑浊。", "tip": "“二氧化碳使石蕊变红”的前提是石蕊纸花“湿润”，干燥的纸花不会变红。", "hard": ""}, {"type": "sci", "level": "容易", "stem": "关于人体的呼吸，下列说法正确的是：", "options": ["肺泡是气体交换的主要场所", "人体呼出的气体中不含有氧气", "呼吸道能使吸入的空气变得温暖、湿润、清洁，是气体交换的场所", "吸气时，肋间肌和膈肌舒张，胸廓容积缩小"], "answer": ["A"], "explain": "肺泡壁很薄、外面缠绕着丰富的毛细血管，是气体交换的主要场所，A 正确。B 错，呼出的气体中仍含少量氧气，只是比吸入时少；C 错，呼吸道只是气体进出的通道，不能进行气体交换；D 错，吸气时肋间肌和膈肌收缩，胸廓容积扩大。", "method": "呼吸题抓两句：“吸气=收缩、胸腔变大；呼气=舒张、胸腔变小”；气体交换只在肺泡等处发生。", "tip": "“呼出的气体不含氧气”是错误说法，只是氧气含量比吸入的气体少。", "hard": ""}, {"type": "math", "level": "容易", "stem": "一组数 2、5、8、11、14……按此规律排列，第 20 项是多少？", "options": ["57", "59", "60", "62"], "answer": ["B"], "explain": "这是首项为 2、公差为 3 的等差数列。第 n 项=首项+(n−1)×公差=2+(20−1)×3=2+57=59，选 B。", "method": "等差数列通项公式 aₙ=a₁+(n−1)d：先定首项和公差，再代入公式。", "tip": "求“第 n 项”要乘(n−1)次公差，别误乘 n 次。", "hard": ""}, {"type": "math", "level": "中等", "stem": "今年父亲比儿子大 28 岁，5 年后父亲的年龄是儿子年龄的 3 倍。今年儿子多少岁？", "options": ["7 岁", "9 岁", "11 岁", "14 岁"], "answer": ["B"], "explain": "年龄差始终不变，5 年后父亲仍比儿子大 28 岁。设 5 年后儿子 x 岁，则父为 x+28，由 x+28=3x 解得 x=14，即 5 年后儿子 14 岁，今年为 14−5=9 岁，选 B。", "method": "年龄问题抓“年龄差不变”，设未知数列方程；注意题目问的是“今年”，算完要再减去年数。", "tip": "解出的是“5 年后”的年龄，别忘了减去 5 年，这是本题最常见的失分点。", "hard": ""}, {"type": "math", "level": "中等", "stem": "一个不透明的盒子里有红、黄、蓝三种颜色的球各若干个（每种颜色都有足够多）。至少摸出多少个球，才能保证一定有 2 个球颜色相同？", "options": ["2 个", "3 个", "4 个", "6 个"], "answer": ["C"], "explain": "最不利的情况是每种颜色各摸出 1 个，共 3 个，再多摸 1 个必与其中一种颜色相同，故至少摸 3+1=4 个，选 C。", "method": "抽屉原理（最不利原则）：要保证有 m 个同色，先让每种颜色各取 m−1 个，再加 1。本题 m=2，即 3×1+1=4。", "tip": "“保证”二字是关键——要按最坏情况算，不能按运气好的情况算。", "hard": ""}, {"type": "logic", "level": "中等", "stem": "刻板印象是指对某一类人或事物形成的概括而固定的看法，这种看法往往忽视个体差异。根据上述定义，下列属于刻板印象的是：", "options": ["小李根据面试表现决定是否录用应聘者", "小王认为“北方人一定都很豪爽”，见到北方同事先入为主", "小张通过考试成绩评估学生本学期的学习情况", "小赵根据医生的建议按时服药"], "answer": ["B"], "explain": "B 中“北方人都豪爽”是对一类人的固定概括、忽视了每个人的个体差异，符合定义。A、C 都是依据具体表现作判断，D 是遵医嘱，均不符合。", "method": "定义判断抓要件：①针对某一类人或事物 ②概括而成、固定不变 ③忽视个体差异。三个要件须同时满足。", "tip": "刻板印象的对象是“一类人/事物”，针对具体个人的评价不算。", "hard": ""}, {"type": "logic", "level": "容易", "stem": "水果：苹果。请从选项中选出与这对关系最为相似的一项：", "options": ["汽车：火车", "蔬菜：白菜", "树木：森林", "钢笔：写字"], "answer": ["B"], "explain": "苹果是水果的一种，二者为种属（包含于）关系；白菜是蔬菜的一种，关系一致，选 B。A 是并列关系，C 是个体与集合，D 是工具与用途，均不同。", "method": "类比先定关系：种属（一个属于另一个）还是并列（同层级并列）。种属可用“A 是 B 的一种”检验。", "tip": "用“……是……的一种”检验种属关系，成立即种属，不成立多半是并列或组成。", "hard": ""}, {"type": "logic", "level": "中等", "stem": "某研究称：常喝绿茶的人患某疾病的概率明显低于不喝绿茶的人，因此喝绿茶能预防这种疾病。以下哪项如果为真，最能削弱上述结论？", "options": ["绿茶中含有多种对人体有益的成分", "调查对象中常喝绿茶的人大多也有规律运动、作息健康的习惯", "该疾病在我国的发病率本来就不高", "少量饮用绿茶不会对身体造成伤害"], "answer": ["B"], "explain": "B 指出常喝绿茶的人同时还具备规律运动、作息健康等习惯，他们患病率低可能源于这些习惯而非绿茶，提出“另有他因”，削弱了“喝绿茶能预防疾病”的因果结论，选 B。A 支持结论；C 与该疾病因果无关；D 只说不伤害身体，不能削弱其预防作用。", "method": "削弱因果论证：寻找“另有他因”——把结果归因于别的因素，即可动摇“正是该因素起作用”。", "tip": "看到“相关性 → 因果”的论证，优先找“其他原因”或“因果倒置”的选项。", "hard": ""}, {"type": "fig", "imgs": ["data/figs/figq_025_1.png", "data/figs/figq_025_2.png"], "stem": "问号处的图形应该是：", "options": ["", "", "", ""], "answer": ["C"], "explain": "左边与右边的对应顺序是:曲线变直线，直线变曲线。"}, {"type": "fig", "imgs": ["data/figs/figq_026_1.png"], "stem": "找出下列图形中不同于其他图形的一项：", "options": ["", "", "", ""], "answer": ["A"], "explain": "图234中大正方形内侧小正方形数量与外侧相同。"}]}, {"set": 12, "date": "2026-10-16", "session": "am", "title": "行测加练 · 科学推理 + 数量关系 + 判断推理（第 12 批）", "items": [{"type": "sci", "level": "容易", "stem": "把一根筷子斜插入盛水的玻璃杯中，从侧面看，筷子好像在水面处“折断”了。这是因为：", "options": ["光的直线传播", "光的反射", "光的折射", "光的色散"], "answer": ["C"], "explain": "光从水斜射入空气时传播方向发生偏折，筷子水下部分的像上移，看起来像折断了，这是光的折射，故选 C。A 是影子成因，B 是平面镜成像，D 是棱镜分光。", "method": "记住“水中物体看起来变浅/折断”＝折射；“水中有倒影”＝反射。", "tip": "折射看“水中之物”，反射看“水面倒影”，别混。", "hard": ""}, {"type": "sci", "level": "容易", "stem": "下列家庭常见物质的水溶液，pH 大于 7 的是：", "options": ["食醋", "柠檬汁", "小苏打水", "汽水"], "answer": ["C"], "explain": "小苏打（碳酸氢钠）水溶液显碱性，pH 大于 7；食醋、柠檬汁、汽水都含酸显酸性，pH 小于 7。故选 C。", "method": "记常见酸：醋、柠檬、汽水（碳酸）；常见碱：小苏打、肥皂水、纯碱。", "tip": "“汽水”因含碳酸而显酸性，别当碱性。", "hard": ""}, {"type": "sci", "level": "中等", "stem": "关于人的性别决定，下列说法正确的是：", "options": ["性别由母亲决定", "男性的性染色体为 XY", "生男生女概率由女方决定", "女性可产生两种卵细胞"], "answer": ["B"], "explain": "男性性染色体为 XY，女性为 XX，故 B 正确。受精时含 X 或 Y 的精子与卵结合决定性别，故生男生女由父方精子类型决定，A、C 错；女性只产生一种卵细胞（含 X），D 错。", "method": "性别决定看“父方的精子是 X 还是 Y”。", "tip": "女性只产生一种卵细胞（X），不要把性别归结为女方。", "hard": ""}, {"type": "sci", "level": "容易", "stem": "两个小灯泡串联在同一电路中，若其中一个灯丝断了，另一个灯泡将：", "options": ["更亮", "变暗", "不亮", "亮度不变"], "answer": ["C"], "explain": "串联电路中电流只有一条路径，一处断路则整个电路断开，另一个灯泡也不亮，故选 C。", "method": "串联“一断全灭”，并联“互不影响”。", "tip": "串联与并联的故障表现正好相反，别记反。", "hard": ""}, {"type": "math", "level": "容易", "stem": "一项工程，甲单独做需 10 天完成，乙单独做需 15 天完成。两人合作，需要多少天完成？", "options": ["5", "6", "8", "12"], "answer": ["B"], "explain": "设工程量为 1，甲效率 1/10、乙效率 1/15，合作效率 = 1/10+1/15 = 1/6，故需 6 天。", "method": "赋值法：设工作总量为 1，用效率和求时间。", "tip": "别把效率直接相加成“天数”，时间要取效率和 1/6 的倒数。", "hard": ""}, {"type": "math", "level": "中等", "stem": "某商品进价 80 元，按标价的 8 折出售，仍可获利 20%。该商品的标价是多少元？", "options": ["100", "120", "150", "160"], "answer": ["B"], "explain": "获利 20% 的售价 = 80×(1+20%) = 96 元；8 折＝标价×0.8，故标价 = 96÷0.8 = 120 元。", "method": "先求实际售价（进价×(1+利润率)），再除以折扣反推标价。", "tip": "利润率的基数是“进价”，不是标价。", "hard": ""}, {"type": "math", "level": "容易", "stem": "从 5 名同学中选出 2 人参加比赛，共有多少种不同的选法？", "options": ["10", "20", "25", "5"], "answer": ["A"], "explain": "从 5 人中选 2 人，与顺序无关，是组合：C(5,2)=5×4÷2=10 种。", "method": "“选出/任选”用组合 C(n,m)；“排队/安排职务”才用排列 A(n,m)。", "tip": "别再乘 2（那是把组合当成排列算了）。", "hard": ""}, {"type": "logic", "level": "中等", "stem": "首因效应：指人们最初接触到的信息所形成的印象，对以后的行为活动和评价的影响。下列属于首因效应的是：", "options": ["小李第一次面试表现出色，此后同事一直认为他能力强", "小王每天坚持跑步锻炼身体", "小张因为朋友推荐而买了某品牌产品", "小赵看到消息后立刻回复了对方"], "answer": ["A"], "explain": "A 中“第一次面试”形成的印象持续影响同事后续评价，符合首因效应定义。B 是习惯行为，C 是他人推荐影响购买，D 是即时回应，均不含“最初印象影响后续评价”这一要件。", "method": "定义判断抓要件：“最初信息”“影响后续评价”，两者缺一不可。", "tip": "别与“近因效应（最近印象影响大）”混，题眼在“最初”。", "hard": ""}, {"type": "logic", "level": "容易", "stem": "医生：手术刀 相当于：", "options": ["农民：田地", "裁缝：剪刀", "学生：课本", "司机：乘客"], "answer": ["B"], "explain": "医生使用手术刀作为职业工具，裁缝使用剪刀作为职业工具，二者关系一致，故选 B。A 是场所关系，C 是学习用具但非职业工具关系，D 是服务对象。", "method": "类比先定关系（此处为“职业—工具”），再逐项比对。", "tip": "“职业＋使用工具”要两边都是工具，别被“课本”这类近似搭子骗到。", "hard": ""}, {"type": "logic", "level": "中等", "stem": "“所有金属都导电，铜是金属，所以铜导电。”以下推理方式与其相同的是：", "options": ["所有鸟都会飞，企鹅是鸟，所以企鹅会飞", "所有学生都要参加考试，小明是学生，所以小明参加考试", "有些花是红色的，玫瑰是花，所以玫瑰是红色的", "所有猫都喜欢鱼，这只动物喜欢鱼，所以它是猫"], "answer": ["B"], "explain": "题干是“所有 M 都是 P，S 是 M，所以 S 是 P”的演绎推理，B 结构相同。A 前提本身有误（企鹅不会飞）；C 是大前提为“有些”，不能必然推出；D 是“肯定后件”的错误推理。", "method": "先抽象出题干的形式结构，再逐项对照是否同构。", "tip": "注意区分“所有…是…”与“有些…是…”，后者推不出确定结论。", "hard": ""}, {"type": "fig", "imgs": ["data/figs/figq_027_1.png", "data/figs/figq_027_2.png"], "stem": "问号处应当是？", "options": ["", "", "", ""], "answer": ["D"], "explain": "后面的图比前面的图增加一个图形，增加的图形的边数是一样的。"}, {"type": "fig", "imgs": ["data/figs/figq_028_1.png", "data/figs/figq_028_2.png"], "stem": "问号处的图形应该是？", "options": ["", "", "", ""], "answer": ["A"], "explain": "每隔3个图形，出现一次黑圆，三角形顺序是两正一倒。"}]}, {"set": 13, "date": "2026-10-16", "session": "pm", "title": "行测加练 · 科学推理 + 数量关系 + 判断推理（第 13 批）", "items": [{"type": "sci", "level": "容易", "stem": "夜间（无光照）绿色植物主要进行的生理活动是：", "options": ["光合作用", "呼吸作用", "蒸腾作用", "受精作用"], "answer": ["B"], "explain": "光合作用需要光，夜间无光不能进行；呼吸作用昼夜不停，故夜间植物主要进行呼吸作用，故选 B。", "method": "记“光合需光、呼吸不停”；夜晚植物也在消耗氧气、放出二氧化碳。", "tip": "别以为植物在夜里“只放氧”，卧室不宜摆放过密绿植。", "hard": ""}, {"type": "sci", "level": "容易", "stem": "用吸管吸饮料时，饮料能进入口中，主要原因是：", "options": ["嘴的吸力直接把饮料拉上来", "大气压把饮料压入口中", "饮料所受的重力作用", "液体分子间的引力"], "answer": ["B"], "explain": "吸管吸气使管内气压减小，外界大气压大于管内气压，把饮料压入口中，故选 B。A 的说法不准确（“吸”并不是靠“拉力”）。", "method": "一切“吸”的现象（吸盘、吸管、注射器吸水）本质都是大气压把物体压上/压入。", "tip": "题眼是“大气压”，别用“吸力”这种模糊表述作答。", "hard": ""}, {"type": "sci", "level": "容易", "stem": "用锅盖盖住着火的油锅可以灭火，其主要灭火原理是：", "options": ["降低油的温度到着火点以下", "隔绝氧气（空气）", "移走可燃物", "降低油的着火点"], "answer": ["B"], "explain": "盖上锅盖后锅内氧气被隔绝，燃烧因缺少助燃物而停止，故选 B。盖盖也能减少热量散失，但主因是隔绝氧气；着火点是物质固有属性，不能“降低”，D 错。", "method": "灭火三途径：清除可燃物、隔绝氧气、降温到着火点以下——看题对号。", "tip": "“着火点”不可改变，凡是说“降低着火点”的选项必错。", "hard": ""}, {"type": "sci", "level": "中等", "stem": "关于人体消化，下列说法正确的是：", "options": ["胆汁中含有消化脂肪的酶", "肝脏是人体最大的消化腺", "胃是吸收养分的主要器官", "淀粉在口腔中不会被初步消化"], "answer": ["B"], "explain": "肝脏是人体最大的消化腺，故 B 正确。胆汁不含消化酶，只起乳化脂肪的作用，A 错；小肠是吸收养分的主要器官，C 错；唾液淀粉酶可在口腔初步消化淀粉，D 错。", "method": "记“最大消化腺＝肝脏”“主要吸收器官＝小肠”“胆汁无酶”。", "tip": "“胆汁不含酶”是高频陷阱，别想当然。", "hard": ""}, {"type": "math", "level": "容易", "stem": "甲、乙两地相距 300 千米，两车同时从两地相向而行，速度分别为 40 千米/时和 60 千米/时。两车几小时后相遇？", "options": ["2", "3", "4", "5"], "answer": ["B"], "explain": "相向而行，相遇时间 = 路程 ÷ 速度和 = 300 ÷ (40+60) = 3 小时。", "method": "相遇问题用“路程÷速度和”；追及问题用“路程差÷速度差”。", "tip": "相向用“速度和”，同向追及用“速度差”，别搞反。", "hard": ""}, {"type": "math", "level": "容易", "stem": "把 20 克盐完全溶解在 180 克水中，所得溶液的浓度（质量分数）是多少？", "options": ["8%", "10%", "11.1%", "20%"], "answer": ["B"], "explain": "溶液质量 = 20+180 = 200 克，浓度 = 20÷200×100% = 10%，故选 B。", "method": "浓度＝溶质÷（溶质＋溶剂），分母是溶液总量。", "tip": "别用 20÷180 得到 11.1% 的干扰项，分母要加溶质。", "hard": ""}, {"type": "math", "level": "中等", "stem": "父亲今年 40 岁，儿子今年 10 岁。多少年后，父亲的年龄是儿子的 2 倍？", "options": ["10", "15", "20", "30"], "answer": ["C"], "explain": "设 x 年后，40+x = 2(10+x)，解得 x = 20，即 20 年后父亲 60 岁、儿子 30 岁，故选 C。", "method": "年龄问题列方程：抓住“年龄差不变”，设未知数解方程。", "tip": "两人年龄同步增长，别只给一方加年份。", "hard": ""}, {"type": "logic", "level": "中等", "stem": "从众心理：指个人受到群体的影响，在知觉、判断、行为上表现出与群体多数一致的现象。下列属于从众心理的是：", "options": ["小王原本不想买，但看到大家都在买，也跟着买了", "小李坚持自己的判断，拒绝了朋友的建议", "小张因为下雨而带了雨伞出门", "小赵看见红灯后停下车来"], "answer": ["A"], "explain": "A 中“原本不想买，因多数人购买而改变行为”，符合从众心理。B 是坚持己见（恰好相反），C 是应对天气，D 是遵守规则，均不因群体多数而改变。", "method": "定义判断抓要件：“受群体影响”＋“与多数一致”，两者缺一不可。", "tip": "B 项“拒绝建议”是反例，正是用来考查是否抓准要件。", "hard": ""}, {"type": "logic", "level": "容易", "stem": "蜜蜂：蜂蜜 相当于：", "options": ["牛：青草", "蜘蛛：蛛网", "鸟：天空", "马：草原"], "answer": ["B"], "explain": "蜜蜂产出蜂蜜，蜘蛛产出蛛网，都是“动物与其产出物”的关系，故选 B。A 是食物关系，C、D 是活动场所关系。", "method": "类比先定关系（此处为“动物—产出物”），再逐项比对。", "tip": "“牛：青草”是吃与被吃，别当成产出关系。", "hard": ""}, {"type": "logic", "level": "中等", "stem": "“只有努力，才能成功。”由此可以推出：", "options": ["努力了就一定能成功", "成功了一定努力过", "不成功就不努力", "不努力也可能成功"], "answer": ["B"], "explain": "“只有 A 才 B”表示 A 是 B 的必要条件，即 B→A：成功→努力，故选 B。A 把必要条件当成充分条件；C 是逆否命题的反向错误（应为“不努力→不成功”）；D 与必要条件含义相反。", "method": "“只有 A 才 B”＝A 必要，B→A；“只要 A 就 B”＝A 充分，A→B。", "tip": "必要与充分方向相反，翻译时务必先定箭头指向。", "hard": ""}, {"type": "fig", "imgs": ["data/figs/figq_029_1.png"], "stem": "找出不同的一项：", "options": ["", "", "", ""], "answer": ["A"], "explain": "轴对称图形。"}, {"type": "fig", "imgs": ["data/figs/figq_030_1.png", "data/figs/figq_030_2.png"], "stem": "问号处的图形应该是？", "options": ["", "", "", ""], "answer": ["D"], "explain": "观察图像可知，一个大的带两个小的相同的图形，只有D符号。"}]}];
